INSERT INTO public.mock_test_questions (mock_test_id, question_text, options, question_type, correct_answer, explanation, topic_id, module_id, question_order, pairs, matches)
VALUES
  ('mock_42_all_1775003803141', 'A large enterprise with over 50 AWS accounts and 100 VPCs needs to establish full mesh connectivity between all VPCs, including shared services VPCs, and provide centralized internet egress. The solution must minimize operational overhead and simplify routing management.', '["Implement AWS Transit Gateway to connect all VPCs and route traffic through a centralized egress VPC.","Configure VPC peering connections between all VPCs to create a full mesh network.","Utilize AWS PrivateLink to establish connections between all VPCs for internal traffic.","Deploy a dedicated Amazon EC2-based routing appliance in each VPC to manage inter-VPC routing."]'::jsonb, 'mcq', '{0}'::integer[], 'Option A (correct) uses AWS Transit Gateway, which is designed for hub-and-spoke networking across many VPCs and accounts. It provides transitive routing, simplifying network architecture and minimizing operational overhead compared to managing numerous individual connections. It also allows for centralized egress through a dedicated VPC. Option B (incorrect) represents anti-pattern ap-1.1-001. VPC peering is non-transitive and requires N*(N-1)/2 connections for a full mesh, making it unmanageable and complex for 100 VPCs. Option C (incorrect) is primarily for securely exposing services between VPCs or accounts, not for general full mesh VPC connectivity and routing. Option D (incorrect) would introduce significant operational overhead and complexity for deployment, management, and scaling of routing appliances across 100 VPCs, increasing costs and management burden.', 42, 'm_42_1', 1, NULL, NULL),
  ('mock_42_all_1775003803141', 'A media company needs to establish a dedicated, high-throughput, and consistently low-latency connection between its on-premises data center and its AWS VPCs in the us-east-1 Region. The connection will carry large video files and real-time streaming data, requiring bandwidth up to 10 Gbps.', '["Establish multiple AWS Site-to-Site VPN connections over the public internet and aggregate their bandwidth.","Implement AWS Direct Connect with a 10 Gbps dedicated connection to a Direct Connect location.","Use AWS Client VPN to allow on-premises servers to connect to the AWS VPC.","Configure a series of VPC peering connections between the on-premises network and AWS."]'::jsonb, 'mcq', '{1}'::integer[], 'Option B (correct) utilizes AWS Direct Connect, which provides a dedicated, private network connection from an on-premises data center to AWS. This ensures consistent network performance, high throughput (up to 100 Gbps), and low latency, making it ideal for large data transfers and real-time workloads. Option A (incorrect) represents anti-pattern ap-1.1-002. AWS Site-to-Site VPN connections traverse the public internet, introducing variable latency and are typically limited to ~1.25 Gbps per tunnel, making them unsuitable as the primary connectivity for high-throughput, latency-sensitive workloads. Aggregating multiple VPNs adds complexity and doesn''t guarantee consistent performance. Option C (incorrect) is designed for individual users to securely access AWS resources, not for high-throughput data center-to-VPC connectivity. Option D (incorrect) is for connecting two AWS VPCs and cannot directly connect an on-premises network to AWS.', 42, 'm_42_1', 2, NULL, NULL),
  ('mock_42_all_1775003803141', 'A software vendor hosts a SaaS application in their AWS account and needs to securely provide access to a specific service endpoint to multiple customer AWS accounts. The solution must ensure traffic does not traverse the public internet and simplify network configuration for customers.', '["Configure a shared AWS Transit Gateway and establish routes to the service endpoint.","Set up VPC peering connections between the vendor''s VPC and each customer''s VPC.","Implement AWS PrivateLink to create a private endpoint for the service in each customer''s VPC.","Deploy a public-facing Application Load Balancer in the vendor''s VPC and whitelist customer IP addresses."]'::jsonb, 'mcq', '{2}'::integer[], 'Option C (correct) uses AWS PrivateLink, which allows customers to privately access services hosted on AWS without using public IPs or traversing the internet. It creates an interface VPC endpoint in the customer''s VPC, making the service appear as if it''s hosted directly in their network, simplifying network configuration and enhancing security. Option A (incorrect) could provide connectivity but is more complex and less granular for sharing a specific service endpoint, typically used for broader VPC-to-VPC or hybrid connectivity. Option B (incorrect) would require managing numerous VPC peering connections, which becomes complex and non-transitive for many customers, and doesn''t inherently provide a ''service endpoint'' abstraction. Option D (incorrect) exposes the service to the public internet, which violates the requirement for traffic not to traverse the public internet and introduces security risks by relying on IP whitelisting.', 42, 'm_42_1', 3, NULL, NULL),
  ('mock_42_all_1775003803141', 'A global corporation operates in several AWS Regions and has established AWS Direct Connect connections from its various data centers to AWS. They need to connect all on-premises networks to multiple VPCs across different AWS Regions using the existing Direct Connect infrastructure, ensuring simplified routing and global connectivity.', '["Establish separate AWS Direct Connect connections from each data center to each AWS Region and configure VPC peering.","Use AWS Site-to-Site VPN connections over the public internet from each data center to each VPC.","Create a Direct Connect Gateway and associate it with AWS Transit Gateways in each Region.","Deploy a dedicated routing instance in a central VPC in each Region and peer them together."]'::jsonb, 'mcq', '{2}'::integer[], 'Option C (correct) leverages a Direct Connect Gateway, which allows you to connect your on-premises network to multiple VPCs in different AWS Regions using a single AWS Direct Connect connection. By associating the Direct Connect Gateway with AWS Transit Gateways in each Region, it provides simplified, transitive routing from on-premises to multiple VPCs across Regions, optimizing connectivity and management. Option A (incorrect) would lead to a complex and expensive setup with redundant Direct Connect connections and does not provide transitive routing across VPCs. Option B (incorrect) uses the public internet, which does not meet the requirement for dedicated, high-performance connectivity provided by Direct Connect, and would be less reliable and secure. Option D (incorrect) would introduce significant operational overhead for managing and scaling custom routing instances across multiple Regions and VPCs.', 42, 'm_42_1', 4, NULL, NULL),
  ('mock_42_all_1775003803141', 'A company''s remote employees need secure access to internal applications hosted in an AWS VPC. The solution must provide client-side VPN access, support various client devices, and integrate with an existing Active Directory for authentication, while minimizing infrastructure management.', '["Deploy a self-managed OpenVPN server on an Amazon EC2 instance in the VPC.","Configure an AWS Site-to-Site VPN connection between each employee''s home network and the VPC.","Implement AWS Client VPN and integrate it with AWS Directory Service for Microsoft Active Directory.","Use AWS Direct Connect to establish a dedicated connection for each remote employee."]'::jsonb, 'mcq', '{2}'::integer[], 'Option C (correct) uses AWS Client VPN, a fully managed service that provides secure access to AWS resources and on-premises networks from any location. It supports various client devices, integrates with AWS Directory Service for Microsoft Active Directory for authentication, and minimizes infrastructure management as it''s a managed service. Option A (incorrect) requires significant operational overhead for deploying, managing, patching, and scaling the OpenVPN server, which goes against minimizing infrastructure management. Option B (incorrect) is designed for connecting entire networks (e.g., data centers) to AWS, not individual remote users, and would be impractical and costly for each employee. Option D (incorrect) provides dedicated network connectivity for on-premises data centers, not individual remote users, and is extremely expensive and complex for this use case.', 42, 'm_42_1', 5, NULL, NULL);

-- ─────────────────────────────────────────
-- Module: m_42_2
-- ─────────────────────────────────────────

INSERT INTO public.mock_test_questions (mock_test_id, question_text, options, question_type, correct_answer, explanation, topic_id, module_id, question_order, pairs, matches)
VALUES
  ('mock_42_all_1775003803141', 'A global enterprise is migrating hundreds of applications to AWS, requiring a multi-account strategy with automated security baselines. They need to ensure that every new AWS account provisioned automatically has a consistent set of security guardrails, logging, and network configurations applied.', '["Manually configure security services and network settings in each new account after provisioning.","Implement AWS Control Tower to automate the provisioning of new accounts with pre-configured guardrails and a landing zone.","Use AWS Organizations to create accounts and then apply Service Control Policies (SCPs) at the root level.","Develop custom AWS Lambda functions to deploy security configurations to new accounts."]'::jsonb, 'mcq', '{1}'::integer[], 'Option B (correct) utilizes AWS Control Tower, which provides an easy way to set up and govern a secure, multi-account AWS environment. It automates the provisioning of new accounts through the Account Factory, ensuring they conform to pre-defined security guardrails, logging, and network configurations, aligning with the requirement for automated security baselines. Option A (incorrect) represents anti-pattern ap-1.2-002. Manually configuring security services and network settings is error-prone, inconsistent, and does not scale for hundreds of accounts. Option C (incorrect) is a foundational step for multi-account management but applying SCPs at the root level (anti-pattern ap-1.2-001) affects all accounts equally, including the management account, and doesn''t automate the deployment of specific security services or network configurations. Option D (incorrect) would require significant development and maintenance effort for custom automation, which is less efficient and robust than a managed service like AWS Control Tower.', 42, 'm_42_2', 6, NULL, NULL),
  ('mock_42_all_1775003803141', 'A company uses AWS Organizations to manage its accounts, structured into OUs for different departments. The security team needs to prevent any account in the ''Development'' OU from launching Amazon EC2 instances in the ''eu-west-2'' Region, while allowing other OUs to operate freely in that Region.', '["Apply an IAM policy to each IAM user and role within the ''Development'' OU to deny EC2 launches in ''eu-west-2''.","Configure AWS Firewall Manager to block EC2 launch requests originating from the ''Development'' OU in ''eu-west-2''.","Implement a Service Control Policy (SCP) at the ''Development'' OU level to deny the ''ec2:RunInstances'' action in ''eu-west-2''.","Use AWS Control Tower to set up a mandatory guardrail that restricts EC2 Region access for the ''Development'' OU."]'::jsonb, 'mcq', '{2}'::integer[], 'Option C (correct) is the most effective and scalable solution. Service Control Policies (SCPs) in AWS Organizations allow you to centrally manage permissions for all accounts in your organization. Applying an SCP at the ''Development'' OU level specifically targets those accounts and prevents them from performing the ''ec2:RunInstances'' action in ''eu-west-2'', without affecting other OUs. Option A (incorrect) is not scalable or efficient for managing many users and roles across multiple accounts; it''s also less robust as new users/roles might be created without the policy. Option B (incorrect) is primarily for managing WAF, Shield, and security groups, not for controlling EC2 launch permissions at a regional level via OUs. Option D (incorrect) is a good option for automated governance, but an SCP is a direct and precise way to enforce this preventive control at the OU level, which is a core capability of AWS Organizations.', 42, 'm_42_2', 7, NULL, NULL),
  ('mock_42_all_1775003803141', 'A consulting firm manages multiple AWS accounts for various clients, all under a single AWS Organization. They need a centralized solution for their consultants to access client accounts using their corporate credentials, ensuring a single sign-on experience and simplified access management.', '["Implement IAM Identity Center (SSO) and configure it with the corporate identity source.","Create individual IAM users in each client account and provide credentials to consultants.","Set up cross-account IAM roles in each client account and configure trust policies.","Use AWS Resource Access Manager (RAM) to share IAM roles across client accounts."]'::jsonb, 'mcq', '{0}'::integer[], 'Option A (correct) uses IAM Identity Center (SSO), which provides centralized access management to multiple AWS accounts and cloud applications with a single set of credentials. It can integrate with an existing corporate identity source (like Active Directory) to provide a seamless single sign-on experience for consultants across all client accounts. Option B (incorrect) is highly unscalable, insecure, and creates significant operational overhead for managing individual credentials across many accounts. Option C (incorrect) is a valid pattern for cross-account access but still requires manual setup of roles in each account and doesn''t provide a centralized identity source or a single sign-on portal like IAM Identity Center. Option D (incorrect) is used for sharing AWS resources like VPC subnets or Transit Gateways, not for sharing IAM roles or providing centralized identity management.', 42, 'm_42_2', 8, NULL, NULL),
  ('mock_42_all_1775003803141', 'A development team needs to share a custom Amazon Machine Image (AMI) and a specific AWS Transit Gateway attachment across several AWS accounts within their AWS Organization. The solution must ensure that the resources remain owned by the central infrastructure account but are usable by other accounts.', '["Utilize AWS Resource Access Manager (RAM) to share the AMI and Transit Gateway attachment with specified accounts or OUs.","Create copies of the AMI in each target account and configure separate Transit Gateway attachments.","Establish VPC peering connections between the central infrastructure account and each development account.","Use AWS Organizations Service Control Policies (SCPs) to grant access to the AMI and Transit Gateway."]'::jsonb, 'mcq', '{0}'::integer[], 'Option A (correct) uses AWS Resource Access Manager (RAM), which allows you to securely share your AWS resources with any AWS account or within your AWS Organization. This is the ideal service for sharing AMIs, Transit Gateway attachments, and other resources while maintaining ownership in the central account. Option B (incorrect) would lead to multiple copies of the AMI, increasing storage costs and management complexity for updates. Creating separate Transit Gateway attachments for each account is redundant if they can be shared. Option C (incorrect) is for direct VPC-to-VPC connectivity and does not facilitate sharing AMIs or Transit Gateway attachments in a managed way. Option D (incorrect) are preventive guardrails that define maximum permissions; they cannot be used to grant access to specific resources like AMIs or Transit Gateway attachments.', 42, 'm_42_2', 9, NULL, NULL),
  ('mock_42_all_1775003803141', 'A security team needs to centrally manage and deploy a consistent set of AWS WAF rules and AWS Shield Advanced protections across all web applications hosted in various AWS accounts within their AWS Organization, ensuring uniform security posture.', '["Manually configure AWS WAF and AWS Shield Advanced in each individual AWS account.","Use AWS Organizations Service Control Policies (SCPs) to enforce WAF and Shield configurations.","Develop custom scripts to deploy WAF rules and Shield protections to each account.","Implement AWS Firewall Manager to centrally configure and deploy AWS WAF and AWS Shield Advanced policies across the organization."]'::jsonb, 'mcq', '{3}'::integer[], 'Option D (correct) uses AWS Firewall Manager, which is a security management service that allows you to centrally configure and manage firewall rules across your accounts and applications in AWS Organizations. It can be used to deploy and manage AWS WAF rules, AWS Shield Advanced protections, and other security services consistently across your entire organization. Option A (incorrect) is highly inefficient, error-prone, and does not scale for a large number of accounts, leading to an inconsistent security posture. Option B (incorrect) are preventive guardrails that define maximum permissions; they cannot be used to actively deploy or configure services like AWS WAF or AWS Shield Advanced. Option C (incorrect) would require significant development and maintenance effort for custom automation, which is less efficient and robust than a managed service like AWS Firewall Manager.', 42, 'm_42_2', 10, NULL, NULL),
  ('mock_42_all_1775003803141', 'A company uses AWS Organizations and wants to ensure that all new accounts created via AWS Control Tower''s Account Factory automatically have specific security logging and monitoring services enabled and configured, without any manual intervention.', '["Manually enable AWS CloudTrail and Amazon CloudWatch in each new account after it is provisioned.","Customize the AWS Control Tower landing zone to include the desired security logging and monitoring configurations.","Apply a Service Control Policy (SCP) at the root of the organization to enforce logging and monitoring.","Use AWS Resource Access Manager (RAM) to share pre-configured logging resources with new accounts."]'::jsonb, 'mcq', '{1}'::integer[], 'Option B (correct) is the most effective approach. AWS Control Tower''s Account Factory allows for customization of the landing zone. By extending or customizing the landing zone, you can define specific security logging (e.g., AWS CloudTrail, Amazon S3 for logs) and monitoring (e.g., Amazon CloudWatch) configurations that are automatically applied to every new account provisioned through the Account Factory, ensuring consistency and compliance. Option A (incorrect) represents anti-pattern ap-1.2-002. Manual configuration is prone to errors, inconsistent, and does not scale for a multi-account environment. Option C (incorrect) represents anti-pattern ap-1.2-001. Applying an SCP at the root affects all accounts and only provides preventive guardrails (e.g., ''deny disabling CloudTrail''); it doesn''t actively enable or configure services. Option D (incorrect) is used for sharing specific resources like VPC subnets or Transit Gateways, not for automatically configuring security logging and monitoring services within new accounts.', 42, 'm_42_2', 11, NULL, NULL);

