INSERT INTO public.mock_test_questions (mock_test_id, question_text, options, question_type, correct_answer, explanation, topic_id, module_id, question_order, pairs, matches)
VALUES
  ('mock_42_all_1775003803141', 'A global financial institution requires a relational database solution that can provide sub-second Recovery Point Objective (RPO) and low Recovery Time Objective (RTO) for its mission-critical application across two AWS Regions. Data loss during a regional disaster must be minimized.', '["Deploy Amazon Aurora Global Database with a primary Region and a secondary Region configured for disaster recovery.","Implement Amazon DynamoDB Global Tables for cross-Region replication.","Set up a standard Amazon RDS Multi-AZ deployment with cross-Region snapshots for disaster recovery.","Use custom scripts to replicate data between two independent Amazon EC2 instances running a database in different Regions."]'::jsonb, 'mcq', '{0}'::integer[], 'Option A (correct) utilizes Amazon Aurora Global Database, which is specifically designed for global applications, allowing a single Amazon Aurora database to span multiple AWS Regions. It provides fast, low-latency global reads and enables rapid disaster recovery with an RPO of typically less than 1 second and an RTO of less than 1 minute, making it ideal for minimizing data loss in a regional disaster. Option B (incorrect) is for NoSQL databases and provides active-active replication, but the scenario specifies a ''relational database''. Option C (incorrect) provides high availability within a single Region (Multi-AZ) and cross-Region snapshots offer disaster recovery, but the RPO would be measured in minutes or hours (based on snapshot frequency), not sub-second, representing anti-pattern ap-1.3-001. Option D (incorrect) would introduce significant operational overhead, complexity, and potential for data inconsistency, making it unsuitable for a mission-critical financial application.', 42, 'm_42_3', 12, NULL, NULL),
  ('mock_42_all_1775003803141', 'A company hosts a public-facing web application across multiple AWS Regions to serve a global user base. They want to improve application performance and availability by routing user traffic to the closest healthy endpoint over the AWS global network, bypassing congested internet paths.', '["Configure Amazon Route 53 with latency-based routing and health checks.","Deploy a global Content Delivery Network (CDN) like Amazon CloudFront.","Set up an AWS Transit Gateway to connect VPCs across different Regions.","Implement AWS Global Accelerator to direct user traffic to optimal application endpoints."]'::jsonb, 'mcq', '{3}'::integer[], 'Option D (correct) uses AWS Global Accelerator, which improves the availability and performance of applications for a global user base. It routes user traffic through the AWS global network infrastructure to the closest healthy endpoint, bypassing congested internet paths, and provides static Anycast IP addresses, which is ideal for improving performance and availability for global applications. Option A (incorrect) provides DNS-based routing, but traffic still traverses the public internet, which can introduce variable latency and performance issues. Option B (incorrect) is primarily for caching static and dynamic content at edge locations to reduce latency, but it doesn''t optimize routing for the application''s backend endpoints themselves in the same way Global Accelerator does. Option C (incorrect) is for connecting VPCs and on-premises networks, not for optimizing global user access to public-facing applications.', 42, 'm_42_3', 13, NULL, NULL),
  ('mock_42_all_1775003803141', 'A development team wants to proactively identify potential weaknesses in their application''s resilience by simulating various failure scenarios, such as CPU spikes or network packet loss, in a controlled environment. They need a service that can inject these faults without requiring extensive custom tooling.', '["Utilize AWS Fault Injection Service (FIS) to run controlled experiments that inject faults into AWS workloads.","Manually shut down Amazon EC2 instances and disconnect network interfaces to simulate failures.","Implement AWS CloudFormation templates to deploy and tear down resources rapidly.","Use Amazon CloudWatch alarms to detect abnormal behavior and trigger recovery actions."]'::jsonb, 'mcq', '{0}'::integer[], 'Option A (correct) uses AWS Fault Injection Service (FIS), a fully managed service for running fault injection experiments on AWS workloads. It allows you to create and run controlled experiments that inject faults, such as CPU stress, network latency, or API throttling, to test the resilience of your applications without requiring extensive custom tooling. Option B (incorrect) is a manual and uncontrolled approach that can be disruptive, difficult to reproduce consistently, and lacks the safety mechanisms of a dedicated fault injection service. Option C (incorrect) is for infrastructure as code and resource provisioning, not for injecting faults into running systems. Option D (incorrect) is for monitoring and alerting, which is reactive, not for proactively injecting faults to test resilience.', 42, 'm_42_3', 14, NULL, NULL),
  ('mock_42_all_1775003803141', 'A critical banking application uses an Amazon Aurora database and must achieve an RPO of zero and an RTO of minutes in the event of a regional disaster. The solution needs to ensure transactional consistency and minimal data loss during failover to a secondary AWS Region.', '["Deploy Amazon Aurora Global Database with a primary cluster in one Region and a secondary cluster in another, configured for managed failover.","Set up Amazon DynamoDB Global Tables for cross-Region replication of the transactional data.","Implement a standard Amazon RDS for Aurora Multi-AZ deployment and rely on cross-Region automated snapshots.","Configure custom database replication between two standalone Amazon EC2 instances running Aurora in different Regions."]'::jsonb, 'mcq', '{0}'::integer[], 'Option A (correct) is the ideal solution. Amazon Aurora Global Database is specifically designed for disaster recovery with minimal data loss (RPO of typically less than 1 second, effectively near-zero) and fast recovery (RTO of less than 1 minute). It provides managed cross-Region replication and a fast, reliable failover mechanism for relational databases, ensuring transactional consistency. Option B (incorrect) is for NoSQL databases, not relational databases like Aurora, and would not meet the application''s specific database requirement. Option C (incorrect) provides high availability within a single Region (Multi-AZ) and cross-Region snapshots for DR, but the RPO would be limited by snapshot frequency (minutes to hours), not near-zero, representing anti-pattern ap-1.3-001. Option D (incorrect) would be complex to manage, difficult to ensure transactional consistency, and would have significant operational overhead, making it unsuitable for a critical banking application.', 42, 'm_42_3', 15, NULL, NULL),
  ('mock_42_all_1775003803141', 'A company wants to improve the performance and reliability of its internal web application, which is accessed by employees globally and hosted in multiple AWS Regions. The solution should route traffic to the nearest healthy application endpoint using the AWS global network backbone.', '["Configure Amazon Route 53 with geolocation routing policies.","Deploy Amazon CloudFront to cache static content closer to users.","Implement AWS Global Accelerator to direct traffic to optimal regional endpoints.","Establish AWS Transit Gateway peering between all regional VPCs."]'::jsonb, 'mcq', '{2}'::integer[], 'Option C (correct) uses AWS Global Accelerator, which enhances the availability and performance of applications by directing user traffic to the nearest healthy endpoint over the AWS global network. This bypasses potential internet congestion and provides static Anycast IP addresses, ensuring consistent performance for global users accessing multi-Region applications. Option A (incorrect) provides DNS-based routing, but traffic still traverses the public internet, which can lead to variable performance. Option B (incorrect) is primarily a content delivery network for caching static and dynamic content, not for optimizing the routing path to the application''s backend endpoints themselves. Option D (incorrect) is for connecting VPCs and on-premises networks within or across Regions, not for optimizing external user access to public-facing applications.', 42, 'm_42_3', 16, NULL, NULL);

-- Update mock test with question count
UPDATE public.mock_tests
SET total_questions = total_questions + 16
WHERE id = 'mock_42_all_1775003803141';

COMMIT;

