INSERT INTO public.mock_test_questions (mock_test_id, question_text, options, question_type, correct_answer, explanation, topic_id, module_id, question_order, pairs, matches)
VALUES
  ('mock_42_all_1775003803141', 'A large enterprise manages hundreds of Amazon EC2 instances across multiple AWS accounts. The operations team spends significant time manually executing routine runbooks for patching, starting/stopping non-production instances, and collecting diagnostic logs. The Solutions Architect needs to implement a solution to automate these operational tasks with the LEAST administrative overhead.', '["Implement AWS Systems Manager Automation documents to define and execute runbooks across accounts and instances.","Develop custom AWS Lambda functions for each operational task, triggered by Amazon CloudWatch Events for scheduling.","Utilize a dedicated Amazon EC2 instance with a cron job to execute shell scripts for managing other instances.","Manually create and update shell scripts on a central Amazon S3 bucket, and SSH into instances to execute them."]'::jsonb, 'mcq', '{0}'::integer[], 'Option A (correct) leverages AWS Systems Manager Automation, which is designed for defining and executing operational runbooks across a fleet of EC2 instances and other AWS resources with minimal administrative overhead. Automation documents provide a standardized, repeatable, and auditable way to manage common operational tasks, reducing manual effort and errors. Option B (incorrect) involves developing and maintaining custom AWS Lambda functions for each task, which introduces significant development and maintenance overhead compared to using pre-built or easily configurable Systems Manager Automation documents. This approach also requires managing permissions for each Lambda function. Option C (incorrect) relies on a single EC2 instance, creating a single point of failure and requiring manual management of the instance, cron jobs, and scripts, which increases operational complexity and reduces scalability. Option D (incorrect) is a highly manual approach that requires SSH access and manual execution, directly contradicting the requirement for automation and introducing high operational overhead and potential for human error.', 44, 'm_44_1', 1, NULL, NULL),
  ('mock_42_all_1775003803141', 'A development team has deployed a new microservices architecture on AWS. While the initial deployment followed some best practices, the company wants to ensure continuous improvement and identify potential architectural risks over time. The Solutions Architect needs a strategy to regularly assess the architecture against AWS best practices and generate actionable improvement plans.', '["Conduct a one-time architecture review using a third-party consultant to identify all current issues.","Implement regular reviews using the AWS Well-Architected Tool to assess the workload against the Framework''s pillars.","Develop custom scripts to analyze AWS CloudFormation templates for common misconfigurations and security issues.","Schedule monthly meetings with the development team to manually discuss operational challenges and potential improvements."]'::jsonb, 'mcq', '{1}'::integer[], 'Option B (correct) involves using the AWS Well-Architected Tool, which allows for regular, structured reviews of workloads against the AWS Well-Architected Framework''s pillars (Operational Excellence, Security, Reliability, Performance Efficiency, Cost Optimization, and Sustainability). This approach provides actionable guidance and helps ensure continuous improvement, aligning with the anti-pattern [ap-3.1-001] by not treating the review as a one-time exercise. Option A (incorrect) represents the anti-pattern [ap-3.1-001] by treating the Well-Architected Framework review as a one-time compliance exercise. Architectures evolve, and a single review will quickly become outdated. Option C (incorrect) focuses only on CloudFormation templates and common misconfigurations, which is a limited scope and does not cover the full breadth of architectural best practices or provide actionable improvement plans across all Well-Architected pillars. Option D (incorrect) relies on manual discussions, which are prone to subjectivity, lack a structured framework, and may miss critical architectural issues that a systematic tool would identify.', 44, 'm_44_1', 2, NULL, NULL),
  ('mock_42_all_1775003803141', 'A company operates a critical web application on Amazon EC2 instances, using Amazon RDS for its database. The operations team frequently struggles with long mean time to resolution (MTTR) for production issues due to scattered monitoring data. They need to improve their observability strategy to quickly correlate metrics, logs, and traces for faster root cause analysis.', '["Configure Amazon CloudWatch to collect basic EC2 metrics and Amazon RDS logs, viewing them in separate dashboards.","Centralize logs in Amazon S3, metrics in Amazon CloudWatch, and traces in AWS X-Ray, then manually correlate data.","Utilize Amazon CloudWatch for metrics and logs, and AWS X-Ray for traces, integrating them for correlated insights and unified dashboards.","Implement a third-party monitoring solution that collects data from all services but requires custom agent installation and management."]'::jsonb, 'mcq', '{2}'::integer[], 'Option C (correct) describes a robust observability strategy using AWS-native services. Amazon CloudWatch provides comprehensive metrics and logs, while AWS X-Ray offers distributed tracing. Integrating these services allows for correlated insights, enabling developers and operations teams to quickly trace requests, identify bottlenecks, and pinpoint the root cause of issues from a unified view, significantly reducing MTTR. Option A (incorrect) collects basic data but keeps it separate, making correlation difficult and time-consuming, which directly hinders faster root cause analysis. Option B (incorrect) centralizes data in different services (S3 for logs, CloudWatch for metrics, X-Ray for traces) but still requires manual correlation, which is inefficient and error-prone, failing to provide quick, integrated insights. Option D (incorrect) introduces a third-party solution, which adds operational overhead for agent installation, management, and licensing, and may not integrate as seamlessly with AWS services as native solutions.', 44, 'm_44_1', 3, NULL, NULL);

-- ─────────────────────────────────────────
-- Module: m_44_3
-- ─────────────────────────────────────────

INSERT INTO public.mock_test_questions (mock_test_id, question_text, options, question_type, correct_answer, explanation, topic_id, module_id, question_order, pairs, matches)
VALUES
  ('mock_42_all_1775003803141', 'A media company runs a popular video streaming service on Amazon EC2 instances behind an Application Load Balancer, backed by an Amazon RDS database. Users report intermittent buffering and slow load times during peak hours. The operations team''s current strategy is to scale out EC2 instances when CPU utilization is high. However, this has not consistently resolved the performance issues. The Solutions Architect needs to identify the actual bottleneck to achieve the MOST effective performance improvement.', '["Utilize AWS X-Ray to trace requests across the application components and Amazon RDS Performance Insights to analyze database queries.","Increase the instance size of the Amazon EC2 instances and Amazon RDS database to provide more compute and memory resources.","Implement an aggressive auto scaling policy for Amazon EC2 instances to add more capacity much faster during peak loads.","Migrate the Amazon RDS database to a larger, provisioned IOPS Amazon EBS volume to improve disk I/O performance."]'::jsonb, 'mcq', '{0}'::integer[], 'Option A (correct) directly addresses the anti-pattern [ap-3.3-001] by focusing on identifying the actual bottleneck before applying scaling solutions. AWS X-Ray provides end-to-end visibility into request flows across distributed applications, helping pinpoint latency issues in specific microservices or integrations. Amazon RDS Performance Insights offers deep visibility into database load, wait events, and top SQL queries, crucial for identifying database-related bottlenecks. This combined approach allows for targeted and effective performance improvements. Option B (incorrect) is a form of vertical scaling without identifying the bottleneck, which might be unnecessary and costly if the issue is not resource capacity but rather inefficient code or queries. Option C (incorrect) is horizontal scaling, which, as stated in the scenario, has not consistently resolved the issues, indicating that the bottleneck might not be EC2 instance count but rather a single-threaded process or a database constraint (anti-pattern [ap-3.3-001]). Option D (incorrect) assumes the bottleneck is disk I/O without profiling, which might not be the case. It''s a specific solution without prior analysis.', 44, 'm_44_3', 4, NULL, NULL),
  ('mock_42_all_1775003803141', 'A financial application uses an Amazon RDS for PostgreSQL instance that experiences slow query execution times, particularly during complex reporting operations. The development team has confirmed that the EC2 application servers are not bottlenecked. The Solutions Architect needs to implement a strategy to optimize the database performance by identifying and resolving inefficient queries.', '["Scale up the Amazon RDS instance to a larger, more powerful instance class to handle increased load.","Leverage Amazon RDS Performance Insights to identify the top SQL queries, wait events, and database bottlenecks.","Migrate the database to Amazon DynamoDB to take advantage of its high-performance NoSQL capabilities.","Implement read replicas for the Amazon RDS instance to offload read traffic from the primary database."]'::jsonb, 'mcq', '{1}'::integer[], 'Option B (correct) is the most effective strategy for optimizing database performance by identifying inefficient queries. Amazon RDS Performance Insights provides a visual dashboard that helps you understand the database load, identify the top SQL queries, users, hosts, and wait events that are consuming database resources. This allows for targeted optimization, such as indexing or query rewriting. Option A (incorrect) is a vertical scaling approach that might temporarily alleviate symptoms but does not address the root cause of inefficient queries, which could lead to continued performance issues and increased costs (anti-pattern [ap-3.3-001]). Option C (incorrect) is a database migration to a different type of database, which is a significant architectural change and may not be suitable for a PostgreSQL relational database without extensive application refactoring. It''s an over-engineered solution for query optimization. Option D (incorrect) offloads read traffic, which can improve overall read performance, but it does not help identify or optimize slow queries on the primary database, especially if the reporting operations are complex writes or require up-to-date data from the primary.', 44, 'm_44_3', 5, NULL, NULL),
  ('mock_42_all_1775003803141', 'An e-commerce company has several Amazon EC2 instances and Amazon RDS databases that were provisioned based on initial estimates. Over time, resource utilization has varied, leading to some instances being over-provisioned and others potentially under-performing. The Solutions Architect needs a continuous strategy to right-size these resources to improve performance and cost-efficiency.', '["Manually review Amazon CloudWatch metrics for each instance and database monthly to identify resizing opportunities.","Implement a custom script that periodically checks resource utilization and recommends new instance types.","Utilize AWS Compute Optimizer to analyze historical utilization and recommend optimal EC2 instance types and RDS instance classes.","Automatically scale down all non-production EC2 instances and RDS databases by one instance size every quarter."]'::jsonb, 'mcq', '{2}'::integer[], 'Option C (correct) is the most efficient and recommended strategy for continuous right-sizing. AWS Compute Optimizer analyzes historical utilization data for EC2 instances, EBS volumes, AWS Lambda functions, and Amazon RDS instances, then recommends optimal resource configurations to improve performance and reduce costs. It automates the analysis that would otherwise be manual and error-prone. Option A (incorrect) is a manual and time-consuming process that is not scalable or efficient for a large number of resources, making it prone to human error and delayed optimization. Option B (incorrect) requires significant development and maintenance effort for a custom script, which would need to replicate the complex analysis capabilities already provided by AWS Compute Optimizer. Option D (incorrect) is a blind reduction strategy that could lead to under-provisioning and performance degradation if not based on actual utilization data, potentially causing application outages.', 44, 'm_44_3', 6, NULL, NULL),
  ('mock_42_all_1775003803141', 'A company is running a CPU-intensive analytics workload on Amazon EC2 instances using x86 processors. They are looking for ways to improve performance and reduce costs for these workloads without significant code refactoring. The Solutions Architect should recommend a strategy that offers a better performance-to-cost ratio.', '["Scale out the existing x86 Amazon EC2 instances horizontally to distribute the workload across more machines.","Upgrade the existing x86 Amazon EC2 instances to the latest generation of x86 processors for incremental performance gains.","Migrate the workload to AWS Graviton-based Amazon EC2 instances, which offer superior price-performance for many workloads.","Offload parts of the analytics workload to AWS Lambda functions, assuming the workload can be broken into serverless tasks."]'::jsonb, 'mcq', '{2}'::integer[], 'Option C (correct) is the most effective strategy for improving performance and reducing costs for CPU-intensive workloads. AWS Graviton processors are custom-designed by AWS and offer a significantly better price-performance ratio compared to x86 processors for a wide range of workloads, including analytics. The migration often requires minimal code changes for applications written in common languages. Option A (incorrect) is a horizontal scaling approach that might increase overall throughput but does not improve the performance-per-core or cost-efficiency of individual instances, potentially leading to higher overall costs. Option B (incorrect) provides incremental performance gains but does not offer the same leap in price-performance as Graviton processors. It''s a less impactful optimization. Option D (incorrect) is a re-architecture to a serverless model, which is a significant change (''without significant code refactoring'' constraint) and might not be suitable for all CPU-intensive analytics workloads, especially if they are long-running or stateful.', 44, 'm_44_3', 7, NULL, NULL);

-- ─────────────────────────────────────────
-- Module: m_44_4
-- ─────────────────────────────────────────

INSERT INTO public.mock_test_questions (mock_test_id, question_text, options, question_type, correct_answer, explanation, topic_id, module_id, question_order, pairs, matches)
VALUES
  ('mock_42_all_1775003803141', 'A critical application experiences occasional outages due to single points of failure in its current architecture, which was designed years ago. The Solutions Architect needs to identify and address these reliability risks to improve the application''s resilience and ensure business continuity. The company wants a structured approach to assess and improve its reliability posture.', '["Conduct a review using the AWS Well-Architected Tool, focusing on the Reliability Pillar, to identify and remediate single points of failure.","Implement a custom script to periodically check the health of all Amazon EC2 instances and restart any failed ones.","Migrate the entire application to a different AWS Region to reduce the risk of regional outages.","Purchase a third-party reliability assessment service to provide an external audit of the current architecture."]'::jsonb, 'mcq', '{0}'::integer[], 'Option A (correct) provides a structured and comprehensive approach to improving reliability. The AWS Well-Architected Tool allows you to review your architecture against the Reliability Pillar of the Well-Architected Framework, which includes guidance on foundational elements, recovery planning, and managing change. This helps identify single points of failure and provides actionable recommendations for remediation. Option B (incorrect) is a reactive and limited approach to self-healing that does not identify or address underlying architectural single points of failure, such as a single database instance or a single Availability Zone deployment. Option C (incorrect) is a significant and costly architectural change that might not be necessary if the single points of failure can be addressed within the current region through multi-AZ deployments or other reliability patterns. It also doesn''t provide a structured assessment of *all* reliability risks. Option D (incorrect) incurs additional cost and might provide a one-time assessment, but it doesn''t integrate with AWS-native tools for continuous improvement or provide the same actionable guidance as the Well-Architected Tool.', 44, 'm_44_4', 8, NULL, NULL),
  ('mock_42_all_1775003803141', 'An operations team manages several critical applications on AWS. They often discover issues reactively through customer complaints, leading to prolonged downtime. The Solutions Architect needs to implement a strategy for proactive issue detection and notification to minimize the impact of potential failures.', '["Periodically review application logs stored in Amazon S3 for error messages and anomalies.","Configure Amazon CloudWatch Alarms on key metrics and create dashboards for real-time operational visibility.","Implement manual health checks on application endpoints every hour using a web browser.","Develop custom scripts to poll the health of Amazon EC2 instances and send email notifications."]'::jsonb, 'mcq', '{1}'::integer[], 'Option B (correct) is the most effective strategy for proactive issue detection. Amazon CloudWatch Alarms can be configured on various metrics (e.g., CPU utilization, network I/O, error rates, latency) to automatically trigger notifications (e.g., via Amazon SNS) when thresholds are breached. CloudWatch Dashboards provide real-time operational visibility, allowing the team to monitor the health and performance of applications proactively. Option A (incorrect) is a reactive approach; reviewing logs in S3 is typically done after an incident or for auditing, not for real-time proactive detection. Option C (incorrect) is a highly manual, inefficient, and non-scalable method for monitoring, prone to human error and delays. Option D (incorrect) requires significant development and maintenance effort for custom scripts, which would duplicate functionality already provided by Amazon CloudWatch with less reliability and integration.', 44, 'm_44_4', 9, NULL, NULL),
  ('mock_42_all_1775003803141', 'A company''s production environment occasionally experiences service degradation when specific application components fail, requiring manual intervention to restart them. This leads to increased Mean Time To Recovery (MTTR). The Solutions Architect needs to implement a self-healing mechanism to automatically remediate these common failures and reduce MTTR.', '["Configure Amazon CloudWatch Alarms to notify the operations team when a component fails, allowing them to manually intervene faster.","Implement a custom AWS Lambda function that monitors Amazon CloudWatch Events for failure signals and attempts to restart services.","Utilize AWS Systems Manager Automation documents, triggered by Amazon CloudWatch Alarms, to automatically restart or recover failed application components.","Set up a dedicated Amazon EC2 instance to continuously run health checks and execute recovery scripts when failures are detected."]'::jsonb, 'mcq', '{2}'::integer[], 'Option C (correct) provides a robust and integrated self-healing mechanism. AWS Systems Manager Automation allows defining runbooks (Automation documents) for common operational tasks, including restarting services or recovering instances. By triggering these Automation documents with Amazon CloudWatch Alarms, the system can automatically respond to detected failures, significantly reducing MTTR without manual intervention. Option A (incorrect) only provides notification, still requiring manual intervention, which does not address the goal of automatic remediation and reducing MTTR. Option B (incorrect) requires custom development and maintenance of Lambda functions for each specific recovery scenario, which can be complex and less standardized than Systems Manager Automation documents. Option D (incorrect) creates a single point of failure (the dedicated EC2 instance) and requires manual management of the instance and scripts, increasing operational overhead and reducing the reliability of the self-healing mechanism itself.', 44, 'm_44_4', 10, NULL, NULL),
  ('mock_42_all_1775003803141', 'A critical application has an Recovery Time Objective (RTO) of 4 hours and an Recovery Point Objective (RPO) of 1 hour, but the current disaster recovery (DR) strategy relies on daily backups and manual restoration, which cannot meet these targets. The Solutions Architect needs to enhance the DR posture to meet the defined RTO/RPO objectives.', '["Increase the frequency of daily backups to hourly, and practice manual restoration more often.","Implement a multi-region active-passive architecture using custom replication scripts for the database.","Utilize the AWS Well-Architected Tool to review the workload''s recovery strategy against the Reliability Pillar and implement recommended improvements.","Deploy a second, identical application stack in a different Availability Zone within the same AWS Region."]'::jsonb, 'mcq', '{2}'::integer[], 'Option C (correct) provides a structured and comprehensive approach to enhancing the DR posture. The AWS Well-Architected Tool, specifically its Reliability Pillar, guides users through best practices for recovery planning, including achieving specific RTO/RPO targets. It helps identify gaps in the current strategy and recommends AWS-native services and architectural patterns to meet the objectives, such as multi-AZ or multi-region deployments, automated backups, and replication. Option A (incorrect) improves RPO slightly but does not address the RTO, as manual restoration is inherently slow and unlikely to meet a 4-hour RTO. Option B (incorrect) is a specific architectural solution that might be part of a DR strategy, but it relies on custom scripting, which increases operational overhead and risk compared to leveraging AWS-native services and a structured framework. Also, without a comprehensive review, it might not be the most appropriate or cost-effective solution. Option D (incorrect) improves high availability within a region but does not provide a disaster recovery solution for regional outages, which is typically what RTO/RPO targets address at this level of criticality.', 44, 'm_44_4', 11, NULL, NULL);

-- ─────────────────────────────────────────
-- Module: m_44_2
-- ─────────────────────────────────────────

INSERT INTO public.mock_test_questions (mock_test_id, question_text, options, question_type, correct_answer, explanation, topic_id, module_id, question_order, pairs, matches)
VALUES
  ('mock_42_all_1775003803141', 'A security team manages a complex AWS environment with multiple accounts and hundreds of resources. They currently use various third-party tools and custom scripts to monitor security events, resulting in fragmented visibility and slow response times. The Solutions Architect needs to implement a solution for centralized security posture management, threat detection, and finding aggregation.', '["Deploy Amazon GuardDuty across all accounts for intelligent threat detection and integrate its findings with AWS Security Hub for centralized aggregation.","Consolidate all security logs into a central Amazon S3 bucket and use Amazon Athena for querying security events.","Implement AWS Config rules to monitor resource compliance and send notifications for non-compliant resources.","Develop custom AWS Lambda functions to parse security logs from various services and send alerts to the security team."]'::jsonb, 'mcq', '{0}'::integer[], 'Option A (correct) provides a comprehensive, AWS-native solution for centralized security posture management. Amazon GuardDuty offers intelligent threat detection by continuously monitoring for malicious activity and unauthorized behavior. AWS Security Hub then aggregates security findings from GuardDuty and other AWS security services (and integrated third-party products) into a single, normalized view, enabling centralized security posture management and faster response. Option B (incorrect) centralizes logs but requires manual querying and analysis, which is not proactive threat detection or centralized finding aggregation. It lacks the intelligence and automation of GuardDuty and Security Hub. Option C (incorrect) focuses on compliance monitoring, which is important but does not provide active threat detection or aggregation of security findings from various sources like GuardDuty does. Option D (incorrect) involves significant custom development and maintenance overhead for parsing and alerting, duplicating functionality already provided by AWS Security Hub and GuardDuty with less robustness and integration.', 44, 'm_44_2', 12, NULL, NULL),
  ('mock_42_all_1775003803141', 'A company recently discovered that an Amazon S3 bucket containing sensitive customer data was publicly accessible due to an misconfigured bucket policy. The Solutions Architect needs a proactive mechanism to identify and prevent unintended external access to resources like S3 buckets, IAM roles, and KMS keys across the AWS environment.', '["Implement AWS IAM Access Analyzer to continuously monitor resource policies and identify external entities with access.","Regularly review AWS CloudTrail logs for ''PutBucketPolicy'' or ''PutRolePolicy'' API calls to detect policy changes.","Configure Amazon GuardDuty to detect unusual API activity that might indicate unauthorized access attempts.","Manually audit all Amazon S3 bucket policies and IAM role trust policies on a weekly basis."]'::jsonb, 'mcq', '{0}'::integer[], 'Option A (correct) is the most effective proactive mechanism for identifying unintended external access. AWS IAM Access Analyzer continuously monitors resource policies (for S3 buckets, IAM roles, KMS keys, SQS queues, and Lambda functions) and identifies external entities that have access to your resources. It helps you identify and refine access before it becomes a security incident. Option B (incorrect) is a reactive approach that detects changes *after* they have occurred, not proactively identifies potential external access. It requires manual review or custom automation to interpret the logs. Option C (incorrect) focuses on detecting malicious activity or unauthorized access attempts, which is important, but it doesn''t proactively identify *unintended external access* granted by policies before an attack occurs. Option D (incorrect) is a highly manual, error-prone, and unscalable approach that would be impractical in a large or evolving AWS environment.', 44, 'm_44_2', 13, NULL, NULL),
  ('mock_42_all_1775003803141', 'A legacy application running on Amazon EC2 instances uses a third-party host-based intrusion detection system (HIDS) that requires manual agent installation, frequent updates, and complex configuration. The security team wants to reduce the operational overhead associated with managing this HIDS while maintaining robust security monitoring. The Solutions Architect should recommend a strategy to migrate to AWS-native security controls.', '["Continue using the third-party HIDS but automate its agent deployment using AWS Systems Manager.","Replace the third-party HIDS with Amazon GuardDuty for intelligent threat detection and continuous monitoring of AWS accounts.","Implement AWS Security Hub to aggregate findings from the existing HIDS and other security tools.","Develop custom scripts to periodically scan EC2 instances for vulnerabilities and report findings to Amazon CloudWatch."]'::jsonb, 'mcq', '{1}'::integer[], 'Option B (correct) directly addresses the goal of migrating to AWS-native controls to reduce operational overhead while maintaining robust security. Amazon GuardDuty is a fully managed threat detection service that continuously monitors for malicious activity and unauthorized behavior to protect your AWS accounts and workloads. It requires no agent installation or management, significantly reducing the operational overhead associated with a third-party HIDS. Option A (incorrect) automates deployment but still retains the operational overhead of managing the third-party HIDS, including its updates, licensing, and configuration, failing to fully reduce the overhead. Option C (incorrect) aggregates findings but does not replace the HIDS itself, meaning the operational overhead of managing the HIDS still exists. Option D (incorrect) involves significant custom development and maintenance, which increases operational overhead rather than reducing it, and would likely be less comprehensive and intelligent than a managed service like GuardDuty.', 44, 'm_44_2', 14, NULL, NULL),
  ('mock_42_all_1775003803141', 'A company operates a fleet of Amazon EC2 instances running various operating systems. Maintaining security compliance requires ensuring all instances are regularly patched against known vulnerabilities. The current process is largely manual and inconsistent, leading to security gaps. The Solutions Architect needs to implement an automated and consistent patching strategy.', '["Manually connect to each Amazon EC2 instance via SSH/RDP and apply patches during scheduled maintenance windows.","Utilize AWS Systems Manager Patch Manager to automate the patching process for EC2 instances across the fleet.","Develop a custom AWS Lambda function to periodically check for missing patches and apply them to instances.","Implement Amazon GuardDuty to detect instances with outdated patches and notify the security team."]'::jsonb, 'mcq', '{1}'::integer[], 'Option B (correct) is the most effective and AWS-native solution for automating and consistently managing patching. AWS Systems Manager Patch Manager automates the process of patching managed instances with security updates and other types of updates. It allows you to define patch baselines, schedule patching operations, and report on compliance, ensuring consistency and reducing manual effort. Option A (incorrect) is a manual, error-prone, and unscalable approach that directly contradicts the need for an automated and consistent strategy. Option C (incorrect) requires significant custom development and maintenance to replicate the robust functionality already provided by Systems Manager Patch Manager, increasing operational overhead. Option D (incorrect) is a threat detection service that can identify vulnerabilities but does not automate the patching process itself. It would only notify, still requiring manual intervention for remediation.', 44, 'm_44_2', 15, NULL, NULL);

-- ─────────────────────────────────────────
-- Module: m_44_5
-- ─────────────────────────────────────────

INSERT INTO public.mock_test_questions (mock_test_id, question_text, options, question_type, correct_answer, explanation, topic_id, module_id, question_order, pairs, matches)
VALUES
  ('mock_42_all_1775003803141', 'A company has several Amazon EC2 instances and Amazon RDS databases that are consistently underutilized, leading to unnecessary cloud spend. The Solutions Architect needs to identify specific opportunities to reduce infrastructure costs by right-sizing these resources without impacting performance.', '["Leverage AWS Compute Optimizer to analyze historical utilization data and recommend optimal EC2 instance types and RDS instance classes.","Implement a strategy to manually review Amazon CloudWatch metrics for each resource and make resizing decisions.","Purchase Amazon EC2 Reserved Instances and Amazon RDS Reserved Instances for all existing resources.","Automatically terminate all Amazon EC2 instances and Amazon RDS databases that have less than 10% CPU utilization over a month."]'::jsonb, 'mcq', '{0}'::integer[], 'Option A (correct) is the most effective and automated approach for identifying cost-saving opportunities through right-sizing. AWS Compute Optimizer analyzes historical utilization metrics for various resources, including EC2 instances and RDS databases, and provides recommendations for optimal instance types that can reduce costs while maintaining or improving performance. Option B (incorrect) is a manual, time-consuming, and error-prone process that is not scalable for a large number of resources and lacks the advanced analytical capabilities of Compute Optimizer. Option C (incorrect) is a cost-saving measure for committed usage but does not address the underlying issue of underutilization. Purchasing Reserved Instances for over-provisioned resources would lock in unnecessary costs. Option D (incorrect) is an aggressive and potentially disruptive approach that could lead to data loss or application outages if resources are terminated without proper analysis of their actual workload patterns and dependencies.', 44, 'm_44_5', 16, NULL, NULL),
  ('mock_42_all_1775003803141', 'A rapidly growing startup is concerned about its increasing AWS bill. While they have some basic cost monitoring, they lack a structured approach to identify and implement cost-saving measures across their entire cloud environment. The Solutions Architect needs a framework to systematically review their architecture for cost optimization opportunities.', '["Manually analyze the AWS Cost and Usage Report (CUR) every month to find high-cost services and resources.","Conduct regular reviews using the AWS Well-Architected Tool, focusing on the Cost Optimization Pillar, to identify and implement best practices.","Implement AWS Budgets to set spending limits and receive alerts when costs exceed predefined thresholds.","Migrate all non-production workloads to Amazon EC2 Spot Instances to reduce compute costs."]'::jsonb, 'mcq', '{1}'::integer[], 'Option B (correct) provides a structured and comprehensive framework for identifying cost optimization opportunities. The AWS Well-Architected Tool, specifically its Cost Optimization Pillar, guides users through best practices for managing costs, including right-sizing, optimizing pricing models, and controlling spending. This systematic approach helps uncover significant savings. Option A (incorrect) is a reactive and manual approach to cost analysis. While CUR is valuable, manually analyzing it without a framework can be overwhelming and may miss systemic cost inefficiencies. Option C (incorrect) is a cost control mechanism that alerts when spending limits are approached or exceeded, but it does not proactively identify architectural cost optimization opportunities or provide guidance on how to reduce costs. Option D (incorrect) is a specific cost-saving tactic for compute, but it''s not a comprehensive framework for identifying all cost optimization opportunities across an entire environment and might not be suitable for all non-production workloads due to its interruptible nature.', 44, 'm_44_5', 17, NULL, NULL),
  ('mock_42_all_1775003803141', 'An organization has several development and test environments that are often left running overnight and on weekends, contributing to unnecessary AWS costs. The Solutions Architect needs a way to pinpoint these underutilized resources to enable targeted cost-saving actions.', '["Generate a detailed AWS Cost and Usage Report (CUR) and manually filter for resource IDs that incur costs outside business hours.","Implement Amazon CloudWatch metrics and dashboards to monitor resource utilization patterns and identify periods of inactivity.","Develop custom scripts to query AWS API for running instances and compare against a predefined schedule of operational hours.","Use AWS Budgets to set alerts for overall account spending, indicating when costs are higher than expected."]'::jsonb, 'mcq', '{1}'::integer[], 'Option B (correct) is the most effective and AWS-native way to pinpoint underutilized resources based on usage patterns. Amazon CloudWatch can collect detailed metrics (e.g., CPU utilization, network I/O) for EC2 instances and other resources. By creating custom dashboards and analyzing these metrics over time, the Solutions Architect can visualize usage patterns, identify periods of inactivity (e.g., overnight, weekends), and thus pinpoint underutilized resources for targeted cost-saving actions like scheduled stopping. Option A (incorrect) provides billing data, but identifying specific underutilized resources and their usage patterns from CUR can be complex and time-consuming, requiring extensive data manipulation. Option C (incorrect) requires significant custom development and maintenance to replicate the monitoring and visualization capabilities already provided by Amazon CloudWatch. Option D (incorrect) provides high-level spending alerts but does not pinpoint specific underutilized resources or their usage patterns, making it difficult to identify the root cause of unexpected costs.', 44, 'm_44_5', 18, NULL, NULL),
  ('mock_42_all_1775003803141', 'A software development company wants to reduce costs associated with non-production Amazon EC2 instances and Amazon RDS databases that are only needed during business hours. The current process involves developers manually stopping and starting these resources, which is inconsistent and often forgotten. The Solutions Architect needs to automate this cost-saving measure.', '["Implement AWS Systems Manager Automation documents to define and schedule start/stop actions for non-production resources.","Develop custom AWS Lambda functions triggered by Amazon CloudWatch Events to stop and start instances based on a schedule.","Configure Amazon EC2 Auto Scaling groups to scale down to zero instances during off-hours for non-production environments.","Manually create Amazon CloudWatch Alarms to notify developers to stop instances when utilization is low."]'::jsonb, 'mcq', '{0}'::integer[], 'Option A (correct) is the most efficient and AWS-native solution for automating the start/stop schedule for non-production resources. AWS Systems Manager Automation allows you to create Automation documents that define actions like starting or stopping EC2 instances and RDS databases. These documents can then be scheduled using Systems Manager State Manager or Amazon CloudWatch Events, providing a consistent and automated way to reduce costs by powering down resources when not in use. Option B (incorrect) requires custom development and maintenance of Lambda functions for each resource type and scheduling logic, which introduces more operational overhead compared to using pre-built or easily configurable Systems Manager Automation documents. Option C (incorrect) is primarily for scaling compute capacity based on demand, not for scheduled start/stop of non-production environments, and may not be applicable to RDS databases or single-instance development environments. Option D (incorrect) is a notification-based approach that still relies on manual intervention, failing to meet the requirement for automation and consistency in cost-saving measures.', 44, 'm_44_5', 19, NULL, NULL);

-- Update mock test with question count
UPDATE public.mock_tests
SET total_questions = total_questions + 19
WHERE id = 'mock_42_all_1775003803141';

