INSERT INTO public.mock_test_questions (mock_test_id, question_text, options, question_type, correct_answer, explanation, topic_id, module_id, question_order, pairs, matches)
VALUES
  ('mock_42_all_1775003803141', 'A large enterprise is modernizing a critical, high-traffic monolithic application currently running on-premises. The application experiences unpredictable load spikes, leading to performance issues and high operational costs for scaling. The architecture team wants to migrate to AWS, aiming for a highly scalable, resilient, and cost-optimized solution with the LEAST operational overhead for compute resources.', '["Migrate the application to Amazon ECS on AWS Fargate, utilizing Amazon Aurora Serverless for the database and Amazon S3 for static content.","Rehost the application to Amazon EC2 instances within an Auto Scaling group, using Amazon RDS for the database and Amazon EBS for storage.","Containerize the application and deploy it on Amazon EKS, managing the Kubernetes control plane and worker nodes, with Amazon DynamoDB for the database.","Refactor the application into microservices and deploy them as AWS Lambda functions, using Amazon RDS for the database and Amazon EFS for shared storage."]'::jsonb, 'mcq', '{0}'::integer[], 'Option A (correct) provides a highly scalable, resilient, and cost-optimized solution with the least operational overhead. Amazon ECS on AWS Fargate eliminates the need to manage EC2 instances, providing a serverless compute experience for containers. Amazon Aurora Serverless automatically scales database capacity based on demand and offers a pay-per-use model, reducing operational burden and optimizing costs for variable workloads. Amazon S3 is ideal for cost-effective and highly available static content hosting. Option B (incorrect) involves rehosting to Amazon EC2, which still requires managing EC2 instances, Auto Scaling groups, and Amazon RDS, leading to higher operational overhead compared to Fargate and Aurora Serverless. Option C (incorrect) utilizes Amazon EKS, which, while powerful, involves managing the Kubernetes control plane and worker nodes (even with managed node groups, there''s more operational overhead than Fargate), and Amazon DynamoDB might not be suitable if the application relies heavily on relational data structures without significant refactoring. Option D (incorrect) suggests refactoring to AWS Lambda, which is excellent for operational overhead, but pairing it with Amazon RDS for the database and Amazon EFS for shared storage might introduce latency and complexity for a monolithic application that hasn''t been fully refactored into microservices, and EFS can be more expensive for static content than S3.', 45, 'm_45_3', 1, NULL, NULL),
  ('mock_42_all_1775003803141', 'A manufacturing company processes large datasets from IoT devices in daily batch jobs on-premises. These jobs run on a cluster of servers, which are often underutilized outside of peak processing times. The company wants to migrate this workload to AWS to reduce infrastructure costs and management overhead, paying only for the compute resources consumed during the batch processing. Which AWS service combination is MOST suitable?', '["Utilize AWS Batch to run containerized jobs on Amazon EC2 Spot Instances, storing input and output data in Amazon S3.","Deploy a cluster of Amazon EC2 instances with Auto Scaling, running custom scripts for job scheduling and processing, storing data on Amazon EBS.","Refactor the batch jobs into AWS Lambda functions, triggering them with Amazon EventBridge, and storing data in Amazon DynamoDB.","Migrate the jobs to Amazon EKS, managing a Kubernetes cluster to orchestrate batch workloads, with Amazon EFS for shared storage."]'::jsonb, 'mcq', '{0}'::integer[], 'Option A (correct) is the most suitable combination. AWS Batch is a fully managed service that efficiently runs batch computing workloads, allowing users to define jobs and let AWS Batch provision and manage the necessary compute resources (like Amazon EC2 Spot Instances for cost savings). Storing data in Amazon S3 is cost-effective and highly scalable for input/output. This approach significantly reduces operational overhead and optimizes costs by paying only for compute used. Option B (incorrect) involves managing Amazon EC2 instances, Auto Scaling, and custom scheduling, which increases operational overhead compared to AWS Batch. Option C (incorrect) suggests AWS Lambda and Amazon DynamoDB. While serverless, AWS Lambda has execution duration limits (currently 15 minutes) which might not be suitable for long-running batch jobs, and DynamoDB is a NoSQL database, potentially requiring significant data model changes. Option D (incorrect) uses Amazon EKS, which introduces the complexity of managing a Kubernetes cluster, increasing operational overhead compared to AWS Batch for this specific use case.', 45, 'm_45_3', 2, NULL, NULL),
  ('mock_42_all_1775003803141', 'A company stores millions of images in an Amazon S3 bucket. They need to automatically process these images (e.g., resize, watermark, apply metadata) whenever a new image is uploaded, with minimal latency and without provisioning or managing any servers. Which AWS service combination provides the MOST efficient and serverless solution for this requirement?', '["Configure Amazon S3 event notifications to trigger an AWS Lambda function for image processing.","Use Amazon EventBridge to detect S3 object creation events and route them to an Amazon SQS queue for processing by EC2 instances.","Deploy a containerized image processing application on Amazon ECS and use Amazon SQS to queue processing requests.","Set up an Amazon CloudWatch Events rule to periodically scan the S3 bucket and trigger an AWS Step Functions workflow."]'::jsonb, 'mcq', '{0}'::integer[], 'Option A (correct) provides the most efficient and serverless solution. Amazon S3 can directly publish event notifications (e.g., `s3:ObjectCreated:*`) to an AWS Lambda function. This triggers the Lambda function immediately upon upload, allowing for real-time, serverless image processing with minimal latency and no server management. Option B (incorrect) involves Amazon EventBridge routing to an Amazon SQS queue processed by EC2 instances, which introduces server management and higher operational overhead. Option C (incorrect) uses Amazon ECS, which requires managing container infrastructure, and Amazon SQS, which adds a queueing layer but doesn''t achieve the fully serverless compute of Lambda. Option D (incorrect) suggests a periodic scan with Amazon CloudWatch Events and AWS Step Functions, which would introduce latency and is less efficient than direct S3 event notifications for real-time processing.', 45, 'm_45_3', 3, NULL, NULL),
  ('mock_42_all_1775003803141', 'A company plans to rehost 50 Windows and Linux virtual machines from their on-premises VMware environment to Amazon EC2. They require a fully automated solution that handles server replication, machine conversion, and cutover orchestration with minimal manual intervention and a consistent process across all servers. Which AWS service is BEST suited for this rehost migration?', '["Use AWS DataSync to transfer virtual machine disk images to Amazon S3, then manually launch EC2 instances.","Utilize AWS Database Migration Service (DMS) for migrating the server operating systems and applications.","Employ AWS Application Migration Service (MGN) to automate the replication and conversion of servers to EC2.","Deploy a custom script on an Amazon EC2 instance to copy VM files and create AMIs."]'::jsonb, 'mcq', '{2}'::integer[], 'Option C (correct) is best suited for this rehost migration. AWS Application Migration Service (MGN) is the primary AWS service for lift-and-shift (rehost) migrations of physical servers, virtual machines, and cloud instances to AWS. It automates the entire migration process, including continuous replication, automated server conversion, and orchestration of cutover, significantly minimizing manual effort. Option A (incorrect) uses AWS DataSync, which is for file and object data transfer, not for automated server migration and conversion to EC2 instances. Option B (incorrect) suggests AWS Database Migration Service (DMS), which is specifically for database migrations, not for migrating entire servers and applications. Option D (incorrect) involves a custom script, which is manual, error-prone, and lacks the automation, reliability, and features of a dedicated migration service like MGN.', 45, 'm_45_3', 4, NULL, NULL),
  ('mock_42_all_1775003803141', 'A company has decided to migrate a portfolio of over 100 applications and 500 servers from its on-premises data center to AWS. They are using a combination of AWS Application Migration Service (MGN) for rehosting and AWS Database Migration Service (DMS) for database migrations. The migration team needs a centralized tool to track the overall progress of all individual server and database migrations, monitor their status, and identify any issues across these different migration tools. Which AWS service is BEST suited for this purpose?', '["AWS Migration Hub.","AWS Application Discovery Service.","AWS Systems Manager.","AWS Control Tower."]'::jsonb, 'mcq', '{0}'::integer[], 'Option A (correct) is best suited for this purpose. AWS Migration Hub provides a single location to track the progress of application migrations across multiple AWS and partner migration tools, including AWS Application Migration Service (MGN) and AWS Database Migration Service (DMS). It offers a centralized dashboard to monitor the status of individual servers and databases, providing a holistic view of the entire migration portfolio. Option B (incorrect) is AWS Application Discovery Service, which is used for discovering on-premises server inventory, not for tracking migration progress. Option C (incorrect) is AWS Systems Manager, which is for operational insights and management of AWS resources, but not specifically designed as a centralized migration tracking tool across different migration services. Option D (incorrect) is AWS Control Tower, which is for setting up and governing a multi-account AWS environment, not for tracking individual workload migrations.', 45, 'm_45_3', 5, NULL, NULL);

-- ─────────────────────────────────────────
-- Module: m_45_4
-- ─────────────────────────────────────────

INSERT INTO public.mock_test_questions (mock_test_id, question_text, options, question_type, correct_answer, explanation, topic_id, module_id, question_order, pairs, matches)
VALUES
  ('mock_42_all_1775003803141', 'A company operates an on-premises file server storing petabytes of unstructured data, including large media files, accessed by various internal applications using the SMB protocol. They need to migrate this data to AWS, maintaining file system semantics and minimizing application changes, while ensuring high availability and durability. Which approach is MOST suitable for this migration?', '["Migrate the data to Amazon S3 and update applications to use the S3 API for object storage access.","Migrate the data to Amazon FSx for Windows File Server, integrated with AWS Directory Service for Microsoft Active Directory.","Migrate the data to Amazon EFS and reconfigure applications to use NFS for file access.","Migrate the data to Amazon EBS volumes attached to Amazon EC2 instances configured as a file server."]'::jsonb, 'mcq', '{1}'::integer[], 'Option B (correct) is the most suitable approach. Amazon FSx for Windows File Server provides a fully managed, highly available, and durable file system that supports the SMB protocol, making it compatible with existing Windows-based applications without requiring significant changes. Its integration with AWS Directory Service allows seamless authentication and authorization. Option A (incorrect) would require significant application refactoring to use the Amazon S3 API, which violates the requirement of minimizing application changes. Option C (incorrect) involves Amazon EFS, which primarily supports NFS, meaning applications currently using SMB would need to be reconfigured. Option D (incorrect) would require managing EC2 instances and setting up a file server manually, which increases operational overhead and does not provide the same level of managed service benefits as Amazon FSx.', 45, 'm_45_4', 6, NULL, NULL),
  ('mock_42_all_1775003803141', 'A legacy monolithic application has a critical order processing module that frequently experiences bottlenecks and failures under heavy load, impacting customer experience. The development team wants to modernize this module by decoupling it from the monolith, making it highly available, scalable, and resilient to individual component failures, with minimal changes to the existing application''s API calls. Which architectural pattern is MOST appropriate?', '["Rehost the entire application to Amazon EC2 instances within an Auto Scaling group and use a load balancer.","Implement a strangler fig pattern by routing order processing requests through Amazon API Gateway to an AWS Lambda function, with Amazon SQS for asynchronous processing.","Refactor the order processing module into a microservice deployed on Amazon EKS, using a dedicated Amazon RDS instance.","Migrate the order processing module to a separate Amazon EC2 instance and use a simple HTTP API for communication."]'::jsonb, 'mcq', '{1}'::integer[], 'Option B (correct) is the most appropriate architectural pattern. The strangler fig pattern allows for gradual modernization by incrementally replacing parts of a monolithic application. Routing requests through Amazon API Gateway to an AWS Lambda function provides a serverless, scalable, and highly available compute layer for the new module. Using Amazon SQS for asynchronous processing further decouples the components, improving resilience by buffering requests and handling failures gracefully, without requiring immediate changes to the existing application''s API calls. Option A (incorrect) is a rehost strategy that moves the problem to the cloud without addressing the underlying architectural issues of the monolithic module. Option C (incorrect) involves a full refactor to Amazon EKS, which is a more significant undertaking and might not align with the ''minimal changes to existing API calls'' constraint initially. Option D (incorrect) simply moves the module to another EC2 instance, which doesn''t inherently improve scalability, resilience, or decoupling, and still requires manual management.', 45, 'm_45_4', 7, NULL, NULL),
  ('mock_42_all_1775003803141', 'A company has an on-premises enterprise application that generates various events (e.g., customer sign-ups, order status updates). They want to capture these events in AWS, filter them based on content, and reliably route them to multiple AWS services (e.g., AWS Lambda for real-time processing, Amazon SQS for batch processing) without tightly coupling the event producers and consumers. Which AWS service is BEST suited for this event-driven architecture?', '["Use Amazon SNS to publish all events to a single topic, with multiple subscriptions for different services.","Utilize Amazon EventBridge to ingest, filter, and route events to various targets based on defined rules.","Implement a custom event broker on Amazon EC2 instances to receive and distribute events.","Send all events to an Amazon SQS queue, and have different services poll the queue for relevant messages."]'::jsonb, 'mcq', '{1}'::integer[], 'Option B (correct) is best suited for this event-driven architecture. Amazon EventBridge is a serverless event bus that makes it easy to connect applications together using data from your own applications, integrated SaaS applications, and AWS services. It allows you to ingest events, define rules with content-based filtering, and route them to multiple targets (AWS Lambda, Amazon SQS, etc.) without tight coupling between producers and consumers. Option A (incorrect) uses Amazon SNS, which is a publish/subscribe service but has more limited filtering capabilities compared to EventBridge''s content-based filtering for complex routing scenarios. Option C (incorrect) involves a custom event broker on Amazon EC2, which increases operational overhead and negates the benefits of a fully managed serverless solution. Option D (incorrect) uses Amazon SQS, which is a message queue and would require each consumer to poll the queue and implement its own filtering logic, leading to more complex consumer applications and less efficient routing for multiple targets.', 45, 'm_45_4', 8, NULL, NULL),
  ('mock_42_all_1775003803141', 'A company has an on-premises network file share containing 20 TB of design documents that are actively being modified by engineers. They need to migrate this data to Amazon S3, ensuring data integrity, continuous synchronization of ongoing changes, and minimal disruption to the engineering team. The migration should be online and handle incremental updates efficiently. Which AWS service is MOST appropriate?', '["Use AWS Snowball Edge Storage Optimized to perform an offline data transfer.","Establish an AWS Direct Connect connection and manually copy files using rsync.","Utilize AWS Storage Gateway File Gateway to provide an S3-backed file share on-premises.","Employ AWS DataSync to perform an online, incremental data transfer to Amazon S3."]'::jsonb, 'mcq', '{3}'::integer[], 'Option D (correct) is the most appropriate service. AWS DataSync is designed for online data transfer between on-premises storage and AWS storage services like Amazon S3. It efficiently handles large-scale transfers, performs incremental updates, maintains data integrity, and can be scheduled for continuous synchronization, making it ideal for active datasets with ongoing changes. Option A (incorrect) uses AWS Snowball Edge, which is for offline data transfer and not suitable for continuous, online synchronization of active data. Option B (incorrect) involves AWS Direct Connect and manual rsync, which provides a dedicated connection but requires significant manual effort for synchronization and error handling. Option C (incorrect) uses AWS Storage Gateway File Gateway, which provides an on-premises file share backed by S3, but its primary purpose is hybrid cloud storage, not a one-time or continuous migration tool like DataSync.', 45, 'm_45_4', 9, NULL, NULL),
  ('mock_42_all_1775003803141', 'A manufacturing company relies on a legacy Enterprise Resource Planning (ERP) system that is highly customized and runs on aging on-premises hardware. The system is expensive to maintain, lacks modern features, and the vendor no longer provides full support. The company wants to move away from this system entirely and replace it with a modern, cloud-native Software-as-a-Service (SaaS) ERP solution to reduce operational burden and gain new functionalities. Which of the 7 Rs of migration BEST describes this strategy?', '["Rehost","Repurchase","Refactor","Replatform"]'::jsonb, 'mcq', '{1}'::integer[], 'Option B (correct) best describes this strategy. ''Repurchase'' (also known as Drop and Shop) involves replacing an existing application with a new, cloud-native SaaS solution. This is ideal when the existing application is outdated, expensive to maintain, and a suitable commercial off-the-shelf product exists that meets business needs, significantly reducing operational burden. Option A (incorrect) ''Rehost'' (lift and shift) involves moving the application to AWS without significant changes, which would not address the desire for new functionalities or reduced operational burden from a legacy system. Option C (incorrect) ''Refactor'' (re-architect) involves re-imagining how the application is architected and developed, which is a significant effort and not the primary goal of replacing it with a SaaS solution. Option D (incorrect) ''Replatform'' (lift-tinker-and-shift) involves making some cloud-native optimizations to the application during migration, but still keeping the core application, which doesn''t align with replacing it entirely with a SaaS product.', 45, 'm_45_4', 10, NULL, NULL);

-- ─────────────────────────────────────────
-- Module: m_45_2
-- ─────────────────────────────────────────

INSERT INTO public.mock_test_questions (mock_test_id, question_text, options, question_type, correct_answer, explanation, topic_id, module_id, question_order, pairs, matches)
VALUES
  ('mock_42_all_1775003803141', 'A financial services company needs to migrate its on-premises Oracle database, which supports a high-transaction online banking application, to AWS. The primary requirements are to achieve significantly improved read performance, maintain high availability, and ensure full ACID compliance. Which AWS database service is the MOST appropriate choice for this scenario?', '["Migrate to Amazon DynamoDB for its high performance and scalability, leveraging global tables for multi-region availability.","Migrate to Amazon RDS for Oracle, utilizing read replicas and Multi-AZ deployments.","Migrate to Amazon Aurora PostgreSQL-Compatible Edition, using Aurora Replicas and Multi-AZ deployments.","Migrate to Amazon OpenSearch Service for its search capabilities and scalability."]'::jsonb, 'mcq', '{2}'::integer[], 'Option C (correct) is the most appropriate choice. Amazon Aurora PostgreSQL-Compatible Edition offers superior performance compared to traditional Amazon RDS, with up to 3x the throughput of standard PostgreSQL. Aurora''s architecture includes up to 15 Aurora Replicas for scaling read operations and automatic failover across Availability Zones for high availability, all while maintaining full ACID compliance. Option A (incorrect) suggests Amazon DynamoDB, which is a NoSQL database and would require significant application refactoring to move from a relational Oracle database, potentially losing ACID compliance benefits. Option B (incorrect) involves Amazon RDS for Oracle, which maintains compatibility but does not offer the same level of performance improvement or cost optimization as Amazon Aurora. Option D (incorrect) proposes Amazon OpenSearch Service, which is a search and analytics engine, not a transactional relational database, and is unsuitable for an online banking application''s primary database.', 45, 'm_45_2', 11, NULL, NULL),
  ('mock_42_all_1775003803141', 'An on-premises data processing pipeline consists of several sequential steps, including data ingestion, transformation, and loading, with conditional logic and error handling. Some steps are long-running and require retries. The company wants to modernize this pipeline to be fully serverless, fault-tolerant, and provide clear visual workflow management and auditing. Which AWS service is BEST suited for orchestrating this workflow?', '["Use Amazon SQS to queue messages between individual AWS Lambda functions for each step.","Orchestrate the workflow using Amazon EventBridge rules to trigger AWS Lambda functions sequentially.","Implement the workflow using AWS Step Functions to coordinate AWS Lambda functions and other services.","Deploy a custom workflow engine on Amazon EC2 instances to manage the sequential steps."]'::jsonb, 'mcq', '{2}'::integer[], 'Option C (correct) is best suited for orchestrating this workflow. AWS Step Functions allows you to define workflows as state machines, visually coordinating multiple AWS services (including AWS Lambda functions) into serverless applications. It provides built-in error handling, retries, parallel execution, and a visual interface for monitoring workflow execution, making it ideal for complex, sequential, and long-running processes. Option A (incorrect) uses Amazon SQS and AWS Lambda, which can decouple components but lacks the inherent workflow orchestration, state management, and visual monitoring capabilities of AWS Step Functions for complex pipelines. Option B (incorrect) uses Amazon EventBridge, which is excellent for event routing but not for orchestrating sequential, stateful workflows with built-in error handling and visual tracking. Option D (incorrect) involves deploying a custom workflow engine on Amazon EC2, which increases operational overhead and negates the benefits of a fully serverless approach.', 45, 'm_45_2', 12, NULL, NULL),
  ('mock_42_all_1775003803141', 'A large e-commerce company needs to migrate its critical on-premises PostgreSQL database, which experiences high transaction volumes, to Amazon RDS for PostgreSQL. The migration must ensure minimal downtime for the production application and maintain continuous data synchronization during the cutover period. A fallback plan to the on-premises database is also required. Which AWS service combination is MOST appropriate for this migration?', '["Perform a full database backup and restore to Amazon RDS, scheduling a maintenance window for the cutover.","Use AWS Application Migration Service (MGN) to replicate the database server as an EC2 instance, then migrate the database.","Utilize AWS Database Migration Service (DMS) for continuous replication, paired with AWS Schema Conversion Tool (SCT) for schema assessment.","Manually export data using `pg_dump` and import into Amazon RDS, then implement a custom replication solution."]'::jsonb, 'mcq', '{2}'::integer[], 'Option C (correct) is the most appropriate service combination. AWS Database Migration Service (DMS) enables continuous data replication from on-premises databases to AWS with minimal downtime, supporting various database engines including PostgreSQL. AWS Schema Conversion Tool (SCT) can be used beforehand to assess and convert the schema if there are incompatibilities, ensuring a smooth migration. This approach allows for a planned cutover window and maintains the ability to roll back to the source database. Option A (incorrect) involves a full backup and restore, which would incur significant downtime, violating the minimal downtime requirement. Option B (incorrect) uses AWS Application Migration Service (MGN), which is primarily for rehosting entire servers, not specifically optimized for live database migration with continuous replication and schema conversion. Option D (incorrect) involves manual `pg_dump` and custom replication, which is complex, error-prone, and requires significant operational effort, lacking the managed benefits and reliability of AWS DMS.', 45, 'm_45_2', 13, NULL, NULL),
  ('mock_42_all_1775003803141', 'A company needs to migrate a legacy, highly customized mainframe database to AWS. Initial assessment reveals that the database schema and data types are proprietary and highly incompatible with standard relational databases like Amazon RDS or even Amazon Aurora. They require a tool to analyze the source schema, identify incompatibilities, and generate a conversion report with recommendations for target AWS database services. Which AWS service is BEST suited for this initial assessment and schema transformation?', '["AWS Database Migration Service (DMS) for direct data migration.","AWS Application Migration Service (MGN) for server-level migration.","AWS Schema Conversion Tool (SCT) for schema assessment and conversion.","AWS DataSync for transferring database files to Amazon S3."]'::jsonb, 'mcq', '{2}'::integer[], 'Option C (correct) is best suited for this initial assessment and schema transformation. AWS Schema Conversion Tool (SCT) is specifically designed to convert existing database schemas from one database engine to another. It analyzes the source database schema, identifies incompatibilities with the target engine, and provides a detailed assessment report along with recommendations and converted code, which is crucial for migrating highly customized and incompatible databases. Option A (incorrect) uses AWS Database Migration Service (DMS), which is for migrating data, but it relies on the schema already being compatible or converted. Option B (incorrect) suggests AWS Application Migration Service (MGN), which is for rehosting entire servers, not for database schema conversion. Option D (incorrect) uses AWS DataSync, which is for file transfer and not relevant for database schema analysis and conversion.', 45, 'm_45_2', 14, NULL, NULL),
  ('mock_42_all_1775003803141', 'A media company has a large, monolithic video processing application running on-premises. The application is critical for daily operations but has accumulated significant technical debt over the years, making it difficult to update. The company needs to migrate this application to AWS quickly to meet a data center decommissioning deadline, with minimal changes to the application code or architecture. They are willing to address technical debt later. Which of the 7 Rs of migration is the MOST appropriate strategy for this initial move?', '["Refactor","Replatform","Rehost","Retire"]'::jsonb, 'mcq', '{2}'::integer[], 'Option C (correct) ''Rehost'' (lift and shift) is the most appropriate strategy for this initial move. Rehosting involves moving an application to AWS with minimal or no changes to its architecture or code. This approach is typically the fastest way to migrate, making it suitable for meeting tight deadlines like data center decommissioning, even if it means deferring technical debt resolution. Option A (incorrect) ''Refactor'' (re-architect) involves significant changes to the application''s architecture and code to take full advantage of cloud-native features, which is time-consuming and doesn''t align with a quick migration. Option B (incorrect) ''Replatform'' (lift-tinker-and-shift) involves making some cloud-native optimizations (e.g., migrating to Amazon RDS from self-managed database) but still requires more effort than a pure rehost. Option D (incorrect) ''Retire'' means decommissioning the application, which is not an option for a critical application.', 45, 'm_45_2', 15, NULL, NULL);

-- ─────────────────────────────────────────
-- Module: m_45_1
-- ─────────────────────────────────────────

INSERT INTO public.mock_test_questions (mock_test_id, question_text, options, question_type, correct_answer, explanation, topic_id, module_id, question_order, pairs, matches)
VALUES
  ('mock_42_all_1775003803141', 'A media company currently uses an on-premises Elasticsearch cluster for its content search and analytics platform. They want to migrate this workload to AWS to reduce infrastructure management overhead, ensure high availability, and maintain compatibility with their existing Kibana dashboards and search APIs. Which AWS service provides the BEST solution for this requirement?', '["Deploy an Elasticsearch cluster on Amazon EC2 instances and manage it manually.","Containerize the Elasticsearch cluster and deploy it on Amazon EKS.","Migrate the data to Amazon DynamoDB and use DynamoDB Streams for search indexing.","Migrate the data to Amazon OpenSearch Service and configure it for high availability."]'::jsonb, 'mcq', '{3}'::integer[], 'Option D (correct) is the best solution. Amazon OpenSearch Service (formerly Amazon Elasticsearch Service) is a fully managed service that makes it easy to deploy, operate, and scale OpenSearch clusters. It provides built-in high availability, automates infrastructure management, and is compatible with existing Elasticsearch APIs and Kibana dashboards, directly addressing the company''s requirements. Option A (incorrect) would require significant manual effort to deploy and manage an Elasticsearch cluster on Amazon EC2, increasing operational overhead. Option B (incorrect) involves Amazon EKS, which still requires managing the Kubernetes environment and the Elasticsearch application within containers, offering less operational simplicity than a fully managed service. Option C (incorrect) suggests Amazon DynamoDB, which is a NoSQL database and not designed for full-text search and analytics, requiring a complete re-architecture of the search platform.', 45, 'm_45_1', 16, NULL, NULL),
  ('mock_42_all_1775003803141', 'A company has a legacy application that uses a commercial relational database with highly variable usage patterns, leading to significant licensing costs and manual effort for scaling during peak times. They want to modernize the database layer to be serverless, automatically scale capacity up and down, and optimize costs based on actual consumption, while maintaining relational data model compatibility. Which AWS database service is the MOST appropriate?', '["Migrate to Amazon RDS for PostgreSQL with a Multi-AZ deployment and read replicas.","Migrate to Amazon DynamoDB for its serverless nature and on-demand capacity.","Migrate to Amazon Aurora Serverless v2, compatible with MySQL or PostgreSQL.","Migrate to Amazon Redshift for its analytical capabilities and managed service benefits."]'::jsonb, 'mcq', '{2}'::integer[], 'Option C (correct) is the most appropriate choice. Amazon Aurora Serverless v2 automatically scales database capacity instantly based on application demand, providing fine-grained capacity adjustments and a pay-per-second billing model, which significantly optimizes costs for variable workloads. It maintains compatibility with MySQL and PostgreSQL, preserving the relational data model. Option A (incorrect) uses Amazon RDS, which requires pre-provisioning capacity and manual scaling, leading to higher costs during idle periods and more operational effort. Option B (incorrect) suggests Amazon DynamoDB, which is a NoSQL database and would require significant application refactoring to move from a relational model. Option D (incorrect) proposes Amazon Redshift, which is a data warehouse service designed for analytical workloads, not an OLTP database for a transactional application.', 45, 'm_45_1', 17, NULL, NULL),
  ('mock_42_all_1775003803141', 'A scientific research institution needs to migrate 800 TB of genomic sequencing data from an on-premises network-attached storage (NAS) device in a remote lab to Amazon S3. The lab has extremely limited internet bandwidth (less than 100 Mbps) and the migration must be completed within a few weeks. Which AWS service is the MOST cost-effective and efficient solution for this large-scale, offline data transfer?', '["Use AWS DataSync to perform an online data transfer over the existing internet connection.","Establish an AWS Direct Connect connection to transfer the data online.","Utilize AWS Snowball Edge Storage Optimized devices for offline data transfer.","Ship hard drives containing the data directly to an AWS data center for ingestion."]'::jsonb, 'mcq', '{2}'::integer[], 'Option C (correct) is the most cost-effective and efficient solution. AWS Snowball Edge Storage Optimized devices are designed for petabyte-scale data transfers into and out of AWS, especially in environments with limited or no internet connectivity. For 800 TB, multiple Snowball Edge devices can be used to perform an offline transfer within the required timeframe. Option A (incorrect) uses AWS DataSync, which is an online data transfer service. Given the extremely limited internet bandwidth, transferring 800 TB online would take an unacceptably long time (months, not weeks). Option B (incorrect) suggests AWS Direct Connect, which provides a dedicated network connection but is an online transfer method and would be expensive and time-consuming to set up for a one-time, large-scale migration with limited bandwidth. Option D (incorrect) is not a standard AWS service for data ingestion and would involve significant logistical challenges and potential security risks.', 45, 'm_45_1', 18, NULL, NULL),
  ('mock_42_all_1775003803141', 'A large enterprise is planning a comprehensive migration of its on-premises data center to AWS. Before initiating any migrations, they need to gain a deep understanding of their existing server inventory, including operating systems, installed applications, running processes, and network dependencies, to accurately group applications and plan migration waves. Which AWS service provides the MOST effective solution for this discovery phase?', '["AWS Migration Hub to track migration progress.","AWS Application Migration Service (MGN) to prepare for server rehosting.","AWS DataSync to transfer data from on-premises storage.","AWS Application Discovery Service to collect detailed on-premises server inventory."]'::jsonb, 'mcq', '{3}'::integer[], 'Option D (correct) provides the most effective solution for the discovery phase. AWS Application Discovery Service helps enterprises plan migration projects by automatically identifying applications, servers, and their dependencies in on-premises data centers. It collects detailed configuration and usage data, including OS, CPU, memory, running processes, and network connections, which is crucial for understanding the environment and planning migration waves. Option A (incorrect) uses AWS Migration Hub, which is for tracking and monitoring the progress of migrations, not for initial discovery. Option B (incorrect) suggests AWS Application Migration Service (MGN), which is for automating the rehost migration itself, not for the initial discovery. Option C (incorrect) uses AWS DataSync, which is for transferring data, not for discovering server inventory and dependencies.', 45, 'm_45_1', 19, NULL, NULL),
  ('mock_42_all_1775003803141', 'A company is conducting a Total Cost of Ownership (TCO) analysis to compare the costs of running their existing on-premises data center versus migrating their workloads to AWS. They need to accurately estimate the potential savings and expenses across various categories, including compute, storage, networking, and database services, for a multi-year period. Which AWS tool is BEST suited for generating a detailed and customized cost comparison for this TCO analysis?', '["AWS Cost Explorer for analyzing current AWS spending.","AWS Budgets for setting cost and usage alerts.","AWS Migration Hub for tracking migration progress.","AWS Pricing Calculator for estimating new AWS deployments and TCO comparisons."]'::jsonb, 'mcq', '{3}'::integer[], 'Option D (correct) is best suited for generating a detailed and customized cost comparison for TCO analysis. AWS Pricing Calculator allows users to estimate the costs of new AWS deployments and perform TCO comparisons between on-premises and AWS environments. It provides detailed breakdowns across various services, allowing for customization based on specific workload requirements and multi-year projections. Option A (incorrect) is AWS Cost Explorer, which is used for visualizing and managing current AWS spending, not for TCO comparisons with on-premises environments. Option B (incorrect) is AWS Budgets, which is used for setting custom cost and usage alerts for existing AWS resources. Option C (incorrect) is AWS Migration Hub, which tracks the progress of migrations, not for TCO analysis.', 45, 'm_45_1', 20, NULL, NULL);

