INSERT INTO public.mock_test_questions (mock_test_id, question_text, options, question_type, correct_answer, explanation, topic_id, module_id, question_order, pairs, matches)
VALUES
  ('mock_42_all_1775004939674', 'A startup is building a new microservices application that processes asynchronous events from an Amazon SQS queue. The application needs to scale dynamically based on message volume, minimize operational overhead for the development team, and support rapid deployments with minimal downtime. Which architecture meets these requirements with the LEAST operational overhead?', '["Deploy the microservices as AWS Lambda functions triggered by the Amazon SQS queue, managed by AWS Serverless Application Model.","Provision Amazon EC2 instances in an Auto Scaling group, running Docker containers for each microservice, with messages pulled from Amazon SQS.","Utilize Amazon ECS on Amazon EC2 instances, managing container orchestration and scaling, with an application polling Amazon SQS for messages.","Implement a custom solution on Amazon EC2 instances to poll Amazon SQS, deploy code using a CI/CD pipeline, and manually manage scaling."]'::jsonb, 'mcq', '{0}'::integer[], 'Option A (correct) leverages AWS Lambda functions, which are inherently serverless, scale automatically based on Amazon SQS queue depth, and require no server management, thus providing the least operational overhead. The AWS Serverless Application Model (SAM) simplifies deployment. Option B (incorrect) involves managing Amazon EC2 instances and an Auto Scaling group, which introduces significant operational overhead compared to serverless. This represents the anti-pattern of choosing a deployment strategy based on operational familiarity rather than application requirements, as EC2 is operationally heavier for stateless, event-driven workloads. Option C (incorrect) uses Amazon ECS on Amazon EC2, which still requires managing the underlying EC2 instances and cluster infrastructure, leading to higher operational overhead than AWS Lambda. Option D (incorrect) is a highly manual approach with Amazon EC2, requiring custom scaling logic and manual management, which directly contradicts the goal of minimizing operational overhead.', 43, 'm_43_1', 1, NULL, NULL),
  ('mock_42_all_1775004939674', 'A financial institution needs to deploy critical updates to its customer-facing web application with zero downtime and the ability to quickly roll back in case of issues. The application runs on containers managed by Amazon ECS. Which deployment strategy should the Solutions Architect recommend to achieve ZERO downtime and RAPID rollback capability?', '["Perform a rolling update by gradually replacing old tasks with new ones within the existing Amazon ECS service.","Implement a blue/green deployment strategy using AWS CodeDeploy to shift traffic between two distinct Amazon ECS service deployments.","Manually update the container images on each Amazon EC2 instance in the Amazon ECS cluster, restarting services one by one.","Use an in-place deployment where the new application version is deployed directly onto the running Amazon ECS tasks, followed by a restart."]'::jsonb, 'mcq', '{1}'::integer[], 'Option B (correct) describes a blue/green deployment strategy, which is ideal for achieving zero downtime and rapid rollback. AWS CodeDeploy facilitates this by provisioning a new environment (green) with the updated application, shifting traffic from the old environment (blue) once validated, and keeping the blue environment available for immediate rollback if issues arise. Option A (incorrect) is a rolling update, which can cause brief periods of reduced capacity or service degradation during the transition, and rollback might be slower and more complex than blue/green. Option C (incorrect) is a manual and highly error-prone process that would certainly lead to downtime and is not suitable for a critical application. Option D (incorrect) implies an in-place update, which is not a standard Amazon ECS deployment type for zero-downtime and would likely cause service interruptions and complex rollbacks.', 43, 'm_43_1', 2, NULL, NULL),
  ('mock_42_all_1775004939674', 'A global e-commerce platform needs to expose a new set of APIs for its mobile application. These APIs must handle millions of requests per day, scale automatically, and incur costs only when actively used. The development team wants to focus solely on business logic and MINIMIZE operational management. Which architecture best meets these requirements?', '["Deploy the APIs on Amazon EC2 instances behind an Application Load Balancer, using an Auto Scaling group.","Implement the APIs as containerized applications on Amazon ECS with AWS Fargate, exposed via an Application Load Balancer.","Use Amazon API Gateway to expose the APIs, backed by AWS Lambda functions for business logic execution.","Set up a dedicated Amazon EKS cluster to host the API microservices, managing Kubernetes deployments and scaling."]'::jsonb, 'mcq', '{2}'::integer[], 'Option C (correct) provides the most serverless and operationally efficient solution. Amazon API Gateway handles API management, authentication, and routing, while AWS Lambda functions execute the business logic without requiring any server provisioning or management. This combination scales automatically, offers a pay-per-use cost model, and allows the development team to focus entirely on code. Option A (incorrect) requires managing Amazon EC2 instances, an Auto Scaling group, and a load balancer, which increases operational overhead. Option B (incorrect) uses AWS Fargate, which reduces some operational burden compared to EC2, but still involves managing ECS services and container images, and does not fully achieve the pay-per-use model of AWS Lambda for idle periods. Option D (incorrect) involves setting up and managing an Amazon EKS cluster, which is a complex task with significant operational overhead, directly contradicting the goal of minimizing management.', 43, 'm_43_1', 3, NULL, NULL);

-- ─────────────────────────────────────────
-- Module: m_43_2
