INSERT INTO public.mock_test_questions (mock_test_id, question_text, options, question_type, correct_answer, explanation, topic_id, module_id, question_order, pairs, matches)
VALUES
  ('mock_42_all_1775004939674', 'A healthcare provider stores patient records in Amazon S3 and requires a disaster recovery strategy with an RPO of less than 15 minutes and an RTO of less than 4 hours. The data must be accessible from a secondary AWS Region in case of a regional outage. Which solution effectively addresses these requirements for cross-Region data recovery?', '["Implement daily batch jobs to copy Amazon S3 objects to a bucket in the secondary Region using AWS DataSync.","Configure Amazon S3 Cross-Region Replication (CRR) on the source bucket to an S3 bucket in the secondary Region.","Regularly create Amazon S3 snapshots and restore them to a new bucket in the secondary Region during a disaster.","Manually upload copies of critical patient records to a separate Amazon S3 bucket in the secondary Region as needed."]'::jsonb, 'mcq', '{1}'::integer[], 'Option B (correct) is the most effective solution for achieving an RPO of less than 15 minutes and ensuring data availability in a secondary Region. Amazon S3 Cross-Region Replication (CRR) automatically and asynchronously copies new objects from a source S3 bucket to a destination S3 bucket in a different AWS Region, typically within minutes, meeting the RPO requirement. Option A (incorrect) uses daily batch jobs, which would result in an RPO of up to 24 hours, failing to meet the <15 minute RPO requirement. Option C (incorrect) involves creating snapshots and restoring them, which is not a native S3 feature and would be a complex, time-consuming process, likely exceeding the RPO and RTO. Option D (incorrect) is a manual process, which is prone to errors, not scalable, and cannot guarantee the specified RPO or RTO.', 43, 'm_43_2', 4, NULL, NULL),
  ('mock_42_all_1775004939674', 'A global analytics company processes large datasets stored in Amazon S3. They need to ensure that their data remains available and consistent even during a regional outage, with minimal manual intervention for failover. Which architectural pattern provides HIGH availability and consistency across regions with MINIMAL manual failover?', '["Use Amazon S3 Lifecycle Policies to move data to a different Region after 30 days, relying on eventual consistency.","Implement Amazon S3 Cross-Region Replication (CRR) with S3 Versioning enabled, and use Amazon Route 53 with failover routing.","Store all data in a single Amazon S3 bucket and rely on AWS global infrastructure for automatic disaster recovery.","Periodically back up the Amazon S3 bucket to an Amazon EBS snapshot and restore it in another Region when needed."]'::jsonb, 'mcq', '{1}'::integer[], 'Option B (correct) provides a robust solution for high availability and consistency with minimal manual failover. Amazon S3 Cross-Region Replication (CRR) automatically replicates objects and their metadata, including S3 Versioning, to a destination bucket in a different region. Combined with Amazon Route 53 failover routing, which can detect primary region failures and automatically redirect traffic to the secondary region, this setup ensures high availability and consistency with minimal manual intervention. Option A (incorrect) uses S3 Lifecycle Policies for data movement, which is not designed for real-time disaster recovery and would result in significant data loss and unavailability during an outage. Option C (incorrect) relies on a single S3 bucket, which, while highly available within a region, does not protect against a full regional outage. Option D (incorrect) is not a valid approach for S3 data; Amazon EBS snapshots are for EC2 volumes, not S3 buckets, and would be a manual, time-consuming process if it were possible.', 43, 'm_43_2', 5, NULL, NULL),
  ('mock_42_all_1775004939674', 'A company operates a critical web application across two AWS Regions for disaster recovery. They need to automatically redirect user traffic to the healthy region if the primary region experiences an outage, based on application health checks. Which Amazon Route 53 configuration should be used to achieve AUTOMATIC traffic redirection?', '["Configure simple routing policy with two A records pointing to each region''s Application Load Balancer.","Use a latency-based routing policy to direct users to the region with the lowest latency, regardless of health.","Set up a weighted routing policy to distribute traffic evenly between regions, without considering health.","Implement a failover routing policy with associated health checks for the primary region''s Application Load Balancer."]'::jsonb, 'mcq', '{3}'::integer[], 'Option D (correct) is the appropriate Amazon Route 53 configuration for automatic traffic redirection based on health. A failover routing policy allows you to specify a primary and secondary resource. Route 53 monitors the health of the primary resource using associated health checks. If the primary resource becomes unhealthy, Route 53 automatically routes traffic to the secondary resource. Option A (incorrect) uses simple routing, which does not incorporate health checks or automatic failover logic. Option B (incorrect) uses latency-based routing, which directs users to the lowest latency endpoint but does not account for the health of the application, potentially sending users to an unhealthy but geographically closer endpoint. Option C (incorrect) uses weighted routing, which distributes traffic based on specified weights but also does not inherently perform health-based failover.', 43, 'm_43_2', 6, NULL, NULL),
  ('mock_42_all_1775004939674', 'A media streaming service stores its video assets in an Amazon S3 bucket. They need to ensure immediate availability of these assets in a separate AWS Region for disaster recovery purposes, without requiring manual copy operations. Which Amazon S3 feature should be configured to meet this requirement for IMMEDIATE availability and NO manual operations?', '["Enable Amazon S3 Cross-Region Replication (CRR) on the source bucket to a destination bucket in the disaster recovery Region.","Create an AWS Backup plan to regularly back up the Amazon S3 bucket and restore it to the disaster recovery Region when needed.","Configure Amazon S3 Event Notifications to trigger an AWS Lambda function that copies new objects to the disaster recovery Region.","Use Amazon S3 Batch Operations to copy all existing and new objects from the primary bucket to the disaster recovery Region daily."]'::jsonb, 'mcq', '{0}'::integer[], 'Option A (correct) is the most effective and fully managed solution. Amazon S3 Cross-Region Replication (CRR) automatically and asynchronously replicates new objects, object updates, and deletes from a source S3 bucket to a destination S3 bucket in a different AWS Region. This ensures immediate availability of assets in the secondary region without any manual intervention. Option B (incorrect) involves AWS Backup, which is suitable for point-in-time recovery but typically has a longer RTO and does not provide immediate availability for new objects. Option C (incorrect) requires custom AWS Lambda code and management, increasing operational overhead compared to native CRR, and might introduce latency or complexity. Option D (incorrect) uses S3 Batch Operations, which is a manual or scheduled process, not providing immediate replication and requiring ongoing management, failing the ''no manual operations'' constraint.', 43, 'm_43_2', 7, NULL, NULL);

