-- Module: m_43_5
-- ─────────────────────────────────────────

INSERT INTO public.mock_test_questions (mock_test_id, question_text, options, question_type, correct_answer, explanation, topic_id, module_id, question_order, pairs, matches)
VALUES
  ('mock_42_all_1775004939674', 'A popular news website experiences high read traffic for its articles, which are stored in a database. The website needs to reduce the load on its primary database and improve page load times for users globally. Which combination of services will best REDUCE database load and IMPROVE global page load times?', '["Implement a read replica for the database and use Amazon S3 to store static content.","Increase the instance size of the database and deploy the website on larger Amazon EC2 instances.","Utilize Amazon CloudFront to cache static and dynamic content, and Amazon ElastiCache to cache database query results.","Migrate the database to Amazon DynamoDB and use Amazon API Gateway for content delivery."]'::jsonb, 'mcq', '{2}'::integer[], 'Option C (correct) is the most comprehensive solution for both reducing database load and improving global page load times. Amazon CloudFront, a global content delivery network (CDN), caches both static and dynamic content at edge locations worldwide, significantly reducing latency for users and offloading requests from the origin. Amazon ElastiCache (e.g., Redis or Memcached) provides an in-memory cache for database query results, drastically reducing the read load on the primary database and speeding up data retrieval for frequently accessed articles. Option A (incorrect) uses a read replica to offload reads, which helps with database load, but Amazon S3 for static content doesn''t inherently improve dynamic content delivery or global page load times for the main application. Option B (incorrect) involves vertical scaling (larger instances), which is a temporary fix, more expensive, and doesn''t address global latency or efficient caching. Option D (incorrect) suggests migrating to Amazon DynamoDB, which might help with scalability but is a significant re-architecture and Amazon API Gateway is for API management, not general content delivery.', 43, 'm_43_5', 8, NULL, NULL),
  ('mock_42_all_1775004939674', 'A global software company distributes large software packages to customers worldwide. They need to ensure low-latency downloads for users in various geographical locations and reduce data transfer costs from their origin Amazon S3 bucket. Which solution effectively provides LOW-LATENCY global downloads and REDUCED data transfer costs?', '["Store the software packages in multiple Amazon S3 buckets across different AWS Regions.","Use Amazon S3 Transfer Acceleration to speed up uploads to the origin S3 bucket.","Distribute the software packages using Amazon CloudFront with the Amazon S3 bucket as the origin.","Implement a custom content delivery network (CDN) on Amazon EC2 instances in multiple Regions."]'::jsonb, 'mcq', '{2}'::integer[], 'Option C (correct) is the most effective solution. Amazon CloudFront is a global content delivery network (CDN) that caches content at edge locations close to users, providing low-latency downloads worldwide. By using an Amazon S3 bucket as the origin, CloudFront also significantly reduces data transfer costs from S3 to the internet, as data transfer from S3 to CloudFront is free. Option A (incorrect) would require managing multiple S3 buckets and complex routing logic, and would still incur egress costs from each S3 bucket. Option B (incorrect) focuses on upload acceleration, not download performance or cost reduction for egress traffic. Option D (incorrect) involves building and managing a custom CDN on Amazon EC2, which is complex, expensive, and requires significant operational overhead, failing the goal of an optimized solution.', 43, 'm_43_5', 9, NULL, NULL),
  ('mock_42_all_1775004939674', 'An online gaming platform uses a relational database to store user profiles and game session data. During peak hours, the database experiences high read contention, leading to slow response times. The platform needs to offload read requests from the database to improve performance. Which service should be implemented to IMPROVE read performance and REDUCE database load?', '["Deploy an Amazon ElastiCache for Redis cluster to cache frequently accessed user profiles and game session data.","Migrate the entire database to a larger Amazon RDS instance type to handle increased read capacity.","Implement application-level caching within the game servers to store user data locally.","Create multiple read replicas for the relational database to distribute the read load."]'::jsonb, 'mcq', '{0}'::integer[], 'Option A (correct) is the most effective solution for offloading read requests and improving performance. Amazon ElastiCache for Redis provides a high-performance, in-memory data store that can cache frequently accessed data, significantly reducing the load on the relational database and improving response times. Option B (incorrect) involves vertical scaling, which is a temporary and often more expensive solution that doesn''t fundamentally change the read contention pattern. Option C (incorrect) describes application-level caching, which can be effective but introduces complexity in cache invalidation and consistency across multiple game servers, representing the anti-pattern of adding caching at the application level without proper invalidation. Option D (incorrect) creating read replicas helps distribute read load, but ElastiCache can provide even faster access to frequently requested data by serving it from memory, further reducing the load on both the primary and read replica databases.', 43, 'm_43_5', 10, NULL, NULL),
  ('mock_42_all_1775004939674', 'A scientific research institution frequently uploads multi-gigabyte datasets to Amazon S3 for analysis. They observe slow upload speeds, especially for larger files, and need to optimize the data ingestion process to complete uploads faster. Which Amazon S3 feature should be utilized to OPTIMIZE upload speeds for multi-gigabyte files?', '["Enable Amazon S3 Transfer Acceleration on the bucket to speed up data transfers over long distances.","Use Amazon S3 Multipart Upload to upload large files in smaller, parallel parts.","Increase the network bandwidth of the Amazon EC2 instance performing the uploads.","Compress the datasets before uploading them to Amazon S3 to reduce file size."]'::jsonb, 'mcq', '{1}'::integer[], 'Option B (correct) is the most effective Amazon S3 feature for optimizing uploads of multi-gigabyte files. Amazon S3 Multipart Upload allows you to upload a single object as a set of parts. Uploading these parts in parallel can significantly decrease the time it takes to upload a large object, and it also improves resilience to network issues. Option A (incorrect) Amazon S3 Transfer Acceleration helps speed up uploads over long distances by routing data through CloudFront edge locations, but Multipart Upload is typically more impactful for very large files. Option C (incorrect) increasing EC2 network bandwidth might help, but it''s an infrastructure change and not an S3-specific optimization. Option D (incorrect) compressing data before upload reduces the total data transferred, which helps, but Multipart Upload directly addresses the performance of transferring large files regardless of compression.', 43, 'm_43_5', 11, NULL, NULL);

-- ─────────────────────────────────────────
-- Module: m_43_4
-- ─────────────────────────────────────────

INSERT INTO public.mock_test_questions (mock_test_id, question_text, options, question_type, correct_answer, explanation, topic_id, module_id, question_order, pairs, matches)
VALUES
  ('mock_42_all_1775004939674', 'A critical internal application for a large enterprise runs on Amazon EC2 instances. The application must maintain high availability within a single AWS Region, even if an Availability Zone becomes unavailable. Which architecture ensures the application MAINTAINS high availability against AZ failures?', '["Deploy all Amazon EC2 instances in a single Availability Zone and rely on automatic recovery mechanisms.","Configure an Amazon EC2 Auto Scaling group with instances distributed across multiple AWS Regions.","Place all Amazon EC2 instances behind an Application Load Balancer in a single Availability Zone.","Distribute Amazon EC2 instances across multiple Availability Zones within an Auto Scaling group behind an Application Load Balancer."]'::jsonb, 'mcq', '{3}'::integer[], 'Option D (correct) is the standard and most effective architecture for high availability within a single AWS Region. By distributing Amazon EC2 instances across multiple Availability Zones using an Auto Scaling group, the application can withstand the failure of an entire AZ. The Application Load Balancer distributes incoming traffic to healthy instances across these AZs, ensuring continuous operation. Option A (incorrect) places all instances in a single AZ, making the application vulnerable to an AZ outage and failing the high availability requirement. Option B (incorrect) distributes instances across multiple AWS Regions, which is for disaster recovery, not high availability within a single region, and adds unnecessary complexity and cost if not required. Option C (incorrect) placing instances behind a load balancer in a single AZ still leaves the application vulnerable to an AZ failure.', 43, 'm_43_4', 12, NULL, NULL),
  ('mock_42_all_1775004939674', 'A data processing pipeline involves multiple independent steps, where the output of one step becomes the input for the next. The company needs to ensure that failures in one step do not halt the entire pipeline and that messages are reliably delivered between steps. Which AWS service should be used to DECOUPLE processing steps for fault tolerance and RELIABLE message delivery?', '["Use Amazon Kinesis Data Streams to stream data between processing steps in real time.","Implement Amazon SQS queues between each processing step to store and deliver messages reliably.","Store intermediate results in an Amazon S3 bucket and use S3 Event Notifications to trigger the next step.","Utilize AWS Step Functions to orchestrate the entire pipeline, with each step as a Lambda function."]'::jsonb, 'mcq', '{1}'::integer[], 'Option B (correct) is the most suitable service for decoupling processing steps and ensuring reliable message delivery. Amazon SQS (Simple Queue Service) provides a fully managed message queuing service that allows asynchronous communication between distributed components. Messages are durably stored in the queue until processed, preventing data loss and ensuring that failures in one step do not halt the entire pipeline. Option A (incorrect) Amazon Kinesis Data Streams is designed for real-time streaming and analytics, which might be an overkill or not the primary decoupling mechanism needed for reliable delivery between independent steps. Option C (incorrect) using S3 for intermediate results and event notifications can work, but SQS is specifically designed for reliable message queuing and decoupling, offering features like dead-letter queues and visibility timeouts that are crucial for robust pipelines. Option D (incorrect) AWS Step Functions orchestrates workflows, which is useful, but SQS is still needed for reliable message passing between potentially long-running or independent tasks within or between state machine executions.', 43, 'm_43_4', 13, NULL, NULL);

-- ─────────────────────────────────────────
-- Module: m_43_6
-- ─────────────────────────────────────────

INSERT INTO public.mock_test_questions (mock_test_id, question_text, options, question_type, correct_answer, explanation, topic_id, module_id, question_order, pairs, matches)
VALUES
  ('mock_42_all_1775004939674', 'A bioinformatics company runs large-scale, fault-tolerant genomic analysis jobs that can be interrupted and resumed. These jobs are not time-sensitive but require significant compute resources. The company wants to minimize the cost of these compute-intensive workloads. Which compute strategy should be implemented to MINIMIZE compute costs for these jobs?', '["Utilize Amazon EC2 Spot Instances for the compute fleet, leveraging their lower cost for interruptible workloads.","Provision Amazon EC2 On-Demand Instances with a fixed capacity to ensure consistent performance.","Purchase Amazon EC2 Reserved Instances for the expected duration of the analysis jobs.","Run the analysis jobs on AWS Lambda functions, leveraging its pay-per-execution model."]'::jsonb, 'mcq', '{0}'::integer[], 'Option A (correct) is the most cost-effective strategy for fault-tolerant, interruptible workloads. Amazon EC2 Spot Instances allow you to bid on unused EC2 capacity, offering significant discounts compared to On-Demand prices. Since the genomic analysis jobs are fault-tolerant and not time-sensitive, they can be interrupted and resumed, making Spot Instances an ideal choice for minimizing compute costs. Option B (incorrect) Amazon EC2 On-Demand Instances are more expensive and do not provide cost optimization for interruptible workloads. Option C (incorrect) Amazon EC2 Reserved Instances provide cost savings for predictable, long-running workloads, but Spot Instances offer even greater savings for fault-tolerant, flexible jobs. Option D (incorrect) AWS Lambda functions have execution duration limits (currently 15 minutes) and memory limits, making them unsuitable for large-scale, compute-intensive genomic analysis jobs that might run for hours or days.', 43, 'm_43_6', 14, NULL, NULL),
  ('mock_42_all_1775004939674', 'A new web application is expected to have highly variable traffic patterns, with periods of no activity and sudden bursts. The development team wants to launch the application with the LEAST possible upfront cost and pay only for the actual compute duration. Which architecture best meets these cost optimization goals?', '["Deploy the application on Amazon EC2 instances within an Auto Scaling group, configured for dynamic scaling.","Implement the application using AWS Lambda functions exposed via Amazon API Gateway.","Utilize Amazon ECS on AWS Fargate, scaling tasks based on CPU utilization metrics.","Provision Amazon EC2 Reserved Instances for a baseline capacity and use On-Demand for spikes."]'::jsonb, 'mcq', '{1}'::integer[], 'Option B (correct) provides the lowest upfront cost and a true pay-per-use model for highly variable workloads. AWS Lambda functions incur costs only when they are actively executing, and Amazon API Gateway also operates on a pay-per-request model. This eliminates costs during periods of no activity and automatically scales to handle bursts without manual intervention or pre-provisioning. Option A (incorrect) Amazon EC2 instances, even with Auto Scaling, incur costs for the running instances, even if CPU utilization is low, and require some upfront configuration. Option C (incorrect) AWS Fargate reduces operational overhead compared to EC2, but still provisions tasks that incur costs for their entire runtime, regardless of active processing, and doesn''t offer the same ''cold start'' cost efficiency as Lambda. Option D (incorrect) Amazon EC2 Reserved Instances require an upfront commitment and are not suitable for highly variable workloads where capacity is often idle.', 43, 'm_43_6', 15, NULL, NULL),
  ('mock_42_all_1775004939674', 'A global content delivery platform serves static assets to users worldwide from an Amazon S3 bucket in a single region. The company observes high data transfer costs for internet egress and wants to reduce these costs while improving content delivery performance. Which solution effectively REDUCES internet egress data transfer costs and IMPROVES content delivery performance?', '["Store copies of the static assets in multiple Amazon S3 buckets across different AWS Regions.","Use Amazon S3 Transfer Acceleration to speed up data transfers to the S3 bucket.","Distribute the static assets globally using Amazon CloudFront with the Amazon S3 bucket as the origin.","Implement a custom caching layer on Amazon EC2 instances in various AWS Regions."]'::jsonb, 'mcq', '{2}'::integer[], 'Option C (correct) is the most effective and cost-optimized solution. Amazon CloudFront caches static assets at edge locations worldwide, significantly reducing latency for users and improving content delivery performance. Crucially, data transfer from Amazon S3 to CloudFront is free, and CloudFront''s egress pricing to the internet is generally lower than direct S3 egress, leading to substantial cost savings on data transfer. This directly addresses the anti-pattern of not optimizing data transfer costs. Option A (incorrect) storing assets in multiple S3 buckets would still incur egress costs from each bucket and require complex routing. Option B (incorrect) Amazon S3 Transfer Acceleration is for speeding up uploads to S3, not for reducing egress costs or improving global download performance. Option D (incorrect) building a custom caching layer on EC2 is complex, expensive, and requires significant operational overhead, making it less cost-effective and efficient than CloudFront.', 43, 'm_43_6', 16, NULL, NULL);

-- ─────────────────────────────────────────
-- Module: m_43_3
-- ─────────────────────────────────────────

INSERT INTO public.mock_test_questions (mock_test_id, question_text, options, question_type, correct_answer, explanation, topic_id, module_id, question_order, pairs, matches)
VALUES
  ('mock_42_all_1775004939674', 'A software company develops a multi-tenant SaaS application that requires strong encryption for customer data at rest. Each customer''s data must be encrypted with a unique, customer-managed key, and the key lifecycle must be fully controlled by the customer. Which AWS Key Management Service (AWS KMS) approach meets these security requirements?', '["Use an AWS-managed key (CMK) provided by AWS KMS for all customer data encryption.","Create a separate customer managed key (CMK) in AWS KMS for each customer, with appropriate IAM policies.","Implement client-side encryption using a single master key stored in AWS Secrets Manager.","Utilize AWS CloudHSM to generate and manage a single hardware-backed key for all tenants."]'::jsonb, 'mcq', '{1}'::integer[], 'Option B (correct) directly addresses the requirement for unique, customer-managed encryption keys with full customer control. By creating a separate customer managed key (CMK) in AWS KMS for each customer, the SaaS application can ensure strong isolation and allow each customer to control their specific key''s lifecycle, including rotation and revocation, through IAM policies. This avoids the anti-pattern of using a single KMS key for all data across all environments and services. Option A (incorrect) uses an AWS-managed key, which does not provide customer control over the key lifecycle or unique keys per customer. Option C (incorrect) client-side encryption with a single master key in Secrets Manager does not provide unique keys per customer or the same level of key management control as AWS KMS. Option D (incorrect) AWS CloudHSM provides hardware-backed keys but using a single key for all tenants would violate the requirement for unique, customer-managed keys per tenant and create a large blast radius if compromised.', 43, 'm_43_3', 17, NULL, NULL),
  ('mock_42_all_1775004939674', 'A research organization stores highly sensitive research data in an Amazon S3 bucket. They need to ensure that this data can only be accessed by specific AWS services within their VPC and prevent any access from the public internet or other AWS accounts. Which combination of security controls effectively RESTRICTS S3 data access?', '["Configure the S3 bucket policy to deny public access and use IAM roles for service access.","Enable S3 Block Public Access settings and encrypt the data using AWS KMS.","Create a VPC endpoint for Amazon S3 and configure both the S3 bucket policy and the VPC endpoint policy to restrict access.","Use Network Access Control Lists (NACLs) on the VPC to block all outbound traffic to the public internet."]'::jsonb, 'mcq', '{2}'::integer[], 'Option C (correct) provides the most robust data perimeter controls. Creating a VPC endpoint for Amazon S3 ensures that traffic to S3 stays within the AWS network and does not traverse the public internet. By configuring both the S3 bucket policy and the VPC endpoint policy, the organization can explicitly define which specific AWS services and IAM principals within their VPC are allowed to access the data, effectively preventing public internet access and unauthorized cross-account access. Option A (incorrect) while denying public access and using IAM roles is good practice, it doesn''t enforce access exclusively from within a VPC or prevent all access from other AWS accounts without a VPC endpoint policy. Option B (incorrect) S3 Block Public Access is essential for preventing public access, and KMS encryption protects data at rest, but neither specifically restricts access to only specific services within a VPC. Option D (incorrect) NACLs operate at the subnet level and can block traffic, but they are not granular enough to control access to specific S3 buckets or services within a VPC endpoint context, and they don''t provide identity-based access control.', 43, 'm_43_3', 18, NULL, NULL),
  ('mock_42_all_1775004939674', 'A large enterprise operates multiple development, staging, and production environments for various applications. They need to establish a robust security posture by ensuring strict isolation between these environments to limit the blast radius of any security incident. Which architectural approach provides the MOST STRICT ISOLATION between these environments?', '["Deploy each environment in a separate AWS account, linked by AWS Organizations, with distinct VPCs and IAM boundaries.","Use separate VPCs for each environment within a single AWS account, applying strict Security Group rules.","Isolate environments using different subnets within a single VPC, with Network Access Control Lists (NACLs) for traffic control.","Implement IAM policies to restrict access to resources based on environment tags within a single AWS account and VPC."]'::jsonb, 'mcq', '{0}'::integer[], 'Option A (correct) provides the most strict isolation. Deploying each environment in a separate AWS account, linked by AWS Organizations, creates the strongest security boundary. Each account can have its own VPCs, IAM users/roles, and resource configurations, effectively limiting the blast radius of a security incident to a single environment/account. This aligns with AWS best practices for workload isolation. Option B (incorrect) using separate VPCs within a single AWS account provides network isolation but does not isolate IAM principals or resource configurations at the account level, meaning a compromise of the account could still impact all VPCs. Option C (incorrect) isolating environments with different subnets within a single VPC offers the weakest isolation, as resources still share the same VPC and account context. Option D (incorrect) relying solely on IAM policies and tags within a single account and VPC is less robust than account-level isolation, as misconfigurations or overly permissive policies could inadvertently grant cross-environment access.', 43, 'm_43_3', 19, NULL, NULL);

