INSERT INTO public.mock_test_questions (mock_test_id, question_text, options, question_type, correct_answer, explanation, topic_id, module_id, question_order, pairs, matches)
VALUES
  ('mock_42_all_1775004939674', 'A global e-commerce company operates a critical order processing application on AWS. The operations team frequently performs manual runbook procedures for routine maintenance and incident response, leading to inconsistent execution and increased mean time to recovery. The company wants to automate these procedures to improve operational efficiency and reduce human error with the LEAST operational overhead.', '["Implement AWS Systems Manager Automation documents to define and execute runbooks, triggered by Amazon CloudWatch Alarms for automated incident response.","Develop custom Python scripts to manage EC2 instances and RDS databases, deploying them to AWS Lambda functions for event-driven execution.","Utilize AWS Well-Architected Tool to conduct regular reviews and manually apply recommendations for improving operational excellence.","Set up Amazon EC2 instances with cron jobs to periodically execute shell scripts for maintenance tasks and rely on email notifications for alerts."]'::jsonb, 'mcq', '{0}'::integer[], 'Option A (correct) leverages AWS Systems Manager Automation, which is specifically designed for defining and executing operational runbooks. Integrating with Amazon CloudWatch Alarms allows for automated triggering of these runbooks in response to specific metrics or events, significantly reducing operational overhead and improving consistency. Option B (incorrect) involves developing custom scripts and deploying them to AWS Lambda, which, while offering automation, requires more development effort and maintenance compared to the native Systems Manager Automation documents for common operational tasks. Option C (incorrect) describes using the AWS Well-Architected Tool, which is excellent for identifying areas of improvement but does not directly automate operational procedures; it provides guidance for manual or other automated implementations. This represents the anti-pattern [ap-3.1-001] of treating Well-Architected reviews as a one-time exercise without implementing continuous automation. Option D (incorrect) relies on traditional cron jobs on EC2 instances, which is a manual and less scalable approach, increasing operational burden for managing scripts, dependencies, and monitoring their execution across a fleet.', 44, 'm_44_1', 1, NULL, NULL),
  ('mock_42_all_1775004939674', 'A software development company is migrating its legacy applications to AWS and aims to achieve a high level of infrastructure as code (IaC) maturity. Currently, deployments involve a mix of manual steps and basic scripting, leading to inconsistencies and slow deployment cycles. The company wants to fully automate its deployments and infrastructure management to reduce errors and accelerate delivery.', '["Continue using existing manual processes for critical deployments and only automate non-production environments.","Adopt AWS Systems Manager Automation documents to orchestrate infrastructure changes and application deployments, integrating with existing CI/CD pipelines.","Conduct a one-time review using the AWS Well-Architected Tool to identify areas for improvement in operational excellence.","Implement a custom configuration management tool on Amazon EC2 instances to manage application deployments."]'::jsonb, 'mcq', '{1}'::integer[], 'Option B (correct) directly supports improving infrastructure as code maturity and automating deployments. AWS Systems Manager Automation documents can define complex workflows for infrastructure provisioning, configuration, and application deployments across various AWS services. Integrating these documents into CI/CD pipelines allows for fully automated, consistent, and repeatable deployments, significantly reducing manual errors and accelerating delivery. Option A (incorrect) maintains manual processes for critical deployments, which contradicts the goal of achieving full automation and high IaC maturity. Option C (incorrect) involves the AWS Well-Architected Tool, which is for architectural review and guidance, not for direct automation of deployments. This option represents the anti-pattern [ap-3.1-001] of treating Well-Architected reviews as a one-time exercise rather than an ongoing improvement process. Option D (incorrect) suggests using a custom configuration management tool, which introduces additional operational overhead for maintenance and management compared to leveraging AWS-native services like Systems Manager Automation.', 44, 'm_44_1', 2, NULL, NULL),
  ('mock_42_all_1775004939674', 'A rapidly growing startup has adopted a microservices architecture running on AWS Lambda, Amazon DynamoDB, and Amazon API Gateway. The operations team struggles to troubleshoot issues effectively due to a lack of visibility into inter-service communication and request flows. They need to implement a comprehensive observability strategy to correlate metrics, logs, and traces for deep insights into application behavior.', '["Configure Amazon CloudWatch Logs for all Lambda functions and manually analyze log groups for errors.","Implement custom application-level logging and metrics within each microservice and store them in Amazon S3.","Integrate AWS X-Ray for distributed tracing across services, configure Amazon CloudWatch for metrics and logs, and correlate them for comprehensive observability.","Deploy a third-party observability solution on Amazon EC2 instances to collect and analyze application data."]'::jsonb, 'mcq', '{2}'::integer[], 'Option C (correct) provides a comprehensive and integrated observability strategy. AWS X-Ray offers end-to-end distributed tracing, visualizing the flow of requests through microservices, identifying performance bottlenecks, and showing service dependencies. Combined with Amazon CloudWatch for collecting metrics (e.g., Lambda invocations, DynamoDB latency) and logs (e.g., application errors, request details), this approach allows for correlation of all three pillars of observability (metrics, logs, traces) to gain deep insights into application behavior and troubleshoot issues effectively. Option A (incorrect) focuses only on CloudWatch Logs, which provides log data but lacks the distributed tracing and integrated metric analysis needed for comprehensive observability in a microservices environment. Option B (incorrect) involves custom logging and metrics to Amazon S3, which requires significant development effort, custom tooling for analysis, and lacks the native integration and correlation capabilities of AWS observability services. Option D (incorrect) introduces a third-party solution, which adds operational overhead for deployment, management, and potential licensing costs compared to leveraging AWS-native services.', 44, 'm_44_1', 3, NULL, NULL),
  ('mock_42_all_1775004939674', 'An enterprise operations team manages a large fleet of Amazon EC2 instances and needs to streamline routine maintenance tasks, such as patching, software installation, and instance restarts. They want to automate these operational runbooks to reduce manual effort, ensure consistency, and minimize human errors across their diverse EC2 environment.', '["Develop custom shell scripts for each maintenance task and execute them manually via SSH on individual EC2 instances.","Implement a configuration management tool like Chef or Puppet on dedicated EC2 instances to manage the fleet.","Leverage AWS Systems Manager Automation documents to define and execute these operational runbooks across the EC2 fleet.","Create Amazon CloudWatch Alarms to detect issues and send notifications to an operations team for manual intervention."]'::jsonb, 'mcq', '{2}'::integer[], 'Option C (correct) is the most appropriate and efficient solution. AWS Systems Manager Automation allows defining operational runbooks as Automation documents, which can then be executed across a fleet of Amazon EC2 instances. This provides a centralized, consistent, and automated way to perform routine maintenance tasks like patching, software installation, and instance restarts, significantly reducing manual effort and errors. Option A (incorrect) involves manual execution of scripts, which is highly inefficient, error-prone, and not scalable for a large fleet. Option B (incorrect) requires deploying and managing a separate configuration management tool, adding operational overhead and complexity compared to using a native AWS service. Option D (incorrect) focuses on alerting, which is important, but it still relies on manual intervention for remediation, failing to meet the requirement for automating operational runbooks.', 44, 'm_44_1', 4, NULL, NULL);

-- ─────────────────────────────────────────
-- Module: m_44_3
-- ─────────────────────────────────────────

INSERT INTO public.mock_test_questions (mock_test_id, question_text, options, question_type, correct_answer, explanation, topic_id, module_id, question_order, pairs, matches)
VALUES
  ('mock_42_all_1775004939674', 'A media streaming service is experiencing intermittent performance degradation during peak hours. Users report buffering and slow loading times. The engineering team suspects a bottleneck in the backend microservices architecture, which involves several AWS Lambda functions, Amazon DynamoDB tables, and Amazon RDS for PostgreSQL. The team needs to accurately identify the root cause of these performance issues with granular detail.', '["Scale out all Amazon EC2 instances and increase Amazon RDS instance sizes to handle the increased load, then monitor if the issue resolves.","Implement AWS X-Ray across the microservices to trace requests end-to-end, combined with Amazon RDS Performance Insights for database-specific bottlenecks.","Configure detailed Amazon CloudWatch metrics and logs for all services and manually analyze them to find correlations.","Use AWS Compute Optimizer to recommend right-sizing for EC2 instances and RDS databases based on historical utilization."]'::jsonb, 'mcq', '{1}'::integer[], 'Option B (correct) is the most effective approach for identifying performance bottlenecks in a distributed microservices architecture. AWS X-Ray provides end-to-end tracing, allowing the team to visualize request flows, identify latency hotspots in Lambda functions, and understand inter-service communication. Amazon RDS Performance Insights offers detailed metrics and query analysis specifically for the database, pinpointing slow queries or resource contention. Option A (incorrect) represents the anti-pattern [ap-3.3-001] of scaling out horizontally without identifying the actual bottleneck. This approach is reactive, potentially costly, and may not solve the underlying problem if the bottleneck is, for example, a poorly optimized database query or a specific Lambda function''s code. Option C (incorrect) involves manual analysis of CloudWatch metrics and logs, which can be time-consuming and challenging to correlate across multiple services, especially for complex distributed systems. Option D (incorrect) uses AWS Compute Optimizer for right-sizing, which is valuable for cost optimization and general performance improvement but is not designed for real-time, granular bottleneck identification within an active performance issue.', 44, 'm_44_3', 5, NULL, NULL),
  ('mock_42_all_1775004939674', 'A financial services company operates a critical online banking application using Amazon RDS for MySQL. Customers are reporting slow transaction times, especially during peak business hours. The database team suspects specific queries or resource contention are causing the slowdowns. They need a solution to identify and tune these database performance bottlenecks effectively.', '["Increase the allocated storage and IOPS for the Amazon RDS instance to improve disk performance.","Enable Amazon RDS Performance Insights to visualize database load, identify top queries, and analyze wait events.","Migrate the Amazon RDS database to a larger EC2 instance type to provide more CPU and memory resources.","Implement Amazon CloudWatch custom metrics to monitor general database CPU and memory utilization."]'::jsonb, 'mcq', '{1}'::integer[], 'Option B (correct) is specifically designed for identifying and tuning database performance bottlenecks. Amazon RDS Performance Insights provides a visual dashboard that helps understand database load, pinpointing the top SQL queries, users, hosts, and wait events that consume the most database resources. This granular visibility is crucial for effective database performance tuning. Option A (incorrect) might help if the bottleneck is storage I/O, but it''s a general approach without first identifying the specific bottleneck. Option C (incorrect) is a form of horizontal scaling without identifying the actual bottleneck, which aligns with the anti-pattern [ap-3.3-001]. If the issue is a poorly indexed query, simply increasing instance size won''t solve it and will increase costs. Option D (incorrect) provides general resource utilization metrics but lacks the deep, query-level insights offered by RDS Performance Insights, making it less effective for specific database tuning.', 44, 'm_44_3', 6, NULL, NULL),
  ('mock_42_all_1775004939674', 'A global online gaming platform experiences intermittent latency spikes that impact user experience, particularly during peak gaming events. The platform''s backend consists of Amazon EC2 instances, AWS Lambda functions, and an Amazon RDS database. The engineering team needs to identify the exact components and code paths causing these latency issues across their distributed application to optimize performance.', '["Increase the instance sizes of all Amazon EC2 instances and Amazon RDS databases to handle higher loads.","Implement detailed Amazon CloudWatch custom metrics for each service and manually review dashboards for anomalies.","Migrate the entire application to a different AWS Region to reduce network latency for a specific user base.","Deploy AWS X-Ray to trace requests end-to-end across EC2, Lambda, and RDS, and use Amazon CloudWatch for service-level metrics and logs."]'::jsonb, 'mcq', '{3}'::integer[], 'Option D (correct) provides the most effective solution for identifying latency bottlenecks in a distributed application. AWS X-Ray offers end-to-end tracing, allowing the engineering team to visualize the entire request flow, identify specific services or code segments contributing to latency, and understand dependencies. Amazon CloudWatch complements this by providing aggregated metrics and logs for each service, enabling a holistic view of performance and health. Option A (incorrect) is a reactive scaling approach that aligns with the anti-pattern [ap-3.3-001] of scaling without identifying the actual bottleneck. This can be costly and may not solve the root cause if the issue is, for example, inefficient code or a poorly optimized database query. Option B (incorrect) relies on manual analysis of CloudWatch metrics, which can be time-consuming and challenging to correlate across complex distributed systems without tracing. Option C (incorrect) is a broad architectural change that might address general network latency but won''t help pinpoint specific application or database bottlenecks within the existing architecture.', 44, 'm_44_3', 7, NULL, NULL),
  ('mock_42_all_1775004939674', 'A data analytics platform uses Amazon RDS for PostgreSQL as its primary data store. The platform is experiencing significant slowdowns during complex query executions, impacting report generation times. The database administrators need a tool to gain deep visibility into the database workload, identify specific slow queries, and understand resource contention to optimize performance.', '["Enable Amazon RDS Performance Insights to monitor database load, identify top SQL queries, and analyze wait events.","Increase the storage capacity and provisioned IOPS of the Amazon RDS instance to improve disk I/O performance.","Migrate the Amazon RDS database to a larger instance class with more CPU and memory resources.","Configure Amazon CloudWatch to collect detailed metrics for CPU utilization, memory usage, and network I/O."]'::jsonb, 'mcq', '{0}'::integer[], 'Option A (correct) is specifically designed to address database performance issues at a granular level. Amazon RDS Performance Insights provides a visual dashboard that helps database administrators understand database load, pinpointing the top SQL queries, users, hosts, and wait events that consume the most database resources. This deep visibility is crucial for identifying specific slow queries and resource contention for effective optimization. Option B (incorrect) might help if the bottleneck is storage I/O, but it''s a general solution without first identifying the specific root cause. Option C (incorrect) is a form of scaling without first identifying the actual bottleneck, which aligns with the anti-pattern [ap-3.3-001]. If the issue is a poorly indexed query, simply increasing instance size won''t solve it and will increase costs. Option D (incorrect) provides general resource utilization metrics but lacks the deep, query-level insights into SQL statements and wait events offered by RDS Performance Insights.', 44, 'm_44_3', 8, NULL, NULL);

-- ─────────────────────────────────────────
-- Module: m_44_4
-- ─────────────────────────────────────────

INSERT INTO public.mock_test_questions (mock_test_id, question_text, options, question_type, correct_answer, explanation, topic_id, module_id, question_order, pairs, matches)
VALUES
  ('mock_42_all_1775004939674', 'A healthcare startup operates a critical patient data management system on AWS, consisting of Amazon EC2 instances, an Amazon RDS database, and Amazon S3 for document storage. The system requires high reliability, and the operations team wants to move from a reactive incident response model to a proactive one, automatically detecting and remediating common operational issues before they impact users. The goal is to enhance system reliability through automated self-healing capabilities.', '["Manually review Amazon CloudWatch dashboards daily to identify anomalies and then initiate remediation steps.","Configure Amazon CloudWatch Alarms to detect specific operational thresholds and trigger AWS Systems Manager Automation documents for automated remediation actions.","Implement a multi-Region active-active architecture to ensure continuous availability, regardless of regional failures.","Regularly perform manual failover tests for Amazon RDS and Amazon EC2 instances to ensure recovery procedures are effective."]'::jsonb, 'mcq', '{1}'::integer[], 'Option B (correct) directly addresses the need for proactive and automated self-healing. Amazon CloudWatch Alarms can monitor key metrics (e.g., CPU utilization, database connections, error rates) and automatically trigger AWS Systems Manager Automation documents when thresholds are breached. These Automation documents can then execute predefined remediation actions, such as restarting an EC2 instance, scaling a resource, or isolating a problematic component, thereby improving reliability with minimal human intervention. Option A (incorrect) relies on manual daily reviews, which is reactive and prone to human error, failing to meet the proactive and automated requirement. Option C (incorrect) describes a multi-Region active-active architecture, which is a high-level reliability strategy for disaster recovery but does not specifically address automated remediation of common operational issues within a single region or application stack. Option D (incorrect) involves manual failover tests, which are important for validating disaster recovery plans but do not provide continuous, automated, proactive remediation for day-to-day operational issues.', 44, 'm_44_4', 9, NULL, NULL),
  ('mock_42_all_1775004939674', 'A rapidly expanding SaaS provider has a complex, evolving architecture on AWS. The development teams frequently introduce new features and services, leading to potential deviations from best practices and increased operational risks. The leadership team wants to establish a continuous process to ensure the architecture consistently adheres to AWS Well-Architected Framework principles and to identify areas for ongoing improvement.', '["Conduct an annual, one-time review of the architecture using the AWS Well-Architected Tool to generate a report.","Develop custom scripts to monitor resource configurations and alert on deviations from a predefined baseline.","Implement a robust observability strategy using Amazon CloudWatch, AWS X-Ray, and Amazon RDS Performance Insights to monitor all aspects of the application.","Integrate regular AWS Well-Architected Framework reviews into the development lifecycle, using the AWS Well-Architected Tool to track and implement improvement plans continuously."]'::jsonb, 'mcq', '{3}'::integer[], 'Option D (correct) directly addresses the need for continuous improvement of architecture against Well-Architected principles. Integrating regular reviews into the development lifecycle ensures that as the architecture evolves, it is consistently evaluated and improved. The AWS Well-Architected Tool provides a structured way to conduct these reviews, track findings, and manage improvement plans. Option A (incorrect) represents the anti-pattern [ap-3.1-001] of treating the Well-Architected Framework review as a one-time compliance exercise. Architecture evolves continuously, and a one-time review will quickly become outdated. Option B (incorrect) focuses on configuration monitoring, which is part of operational excellence but doesn''t encompass the broader architectural best practices covered by the Well-Architected Framework. Option C (incorrect) describes an observability strategy, which is crucial for operational excellence and performance, but it''s a component of a well-architected system, not the framework for continuous architectural review itself.', 44, 'm_44_4', 10, NULL, NULL),
  ('mock_42_all_1775004939674', 'A manufacturing company is expanding its IoT operations on AWS, which involves a complex data ingestion and processing pipeline. The operations team wants to ensure that their cloud environment consistently adheres to best practices for operational excellence, security, and cost optimization, especially as new services and features are continuously added. They need a structured, ongoing approach to identify and implement improvements.', '["Regularly conduct reviews using the AWS Well-Architected Tool to assess the architecture and create improvement plans, integrating these into the development lifecycle.","Focus solely on automating deployment pipelines using AWS CodePipeline and AWS CodeBuild to improve release velocity.","Implement a comprehensive logging strategy using Amazon CloudWatch Logs and Amazon S3 for all application and infrastructure logs.","Perform annual security audits using third-party tools to identify vulnerabilities in the AWS environment."]'::jsonb, 'mcq', '{0}'::integer[], 'Option A (correct) is the most comprehensive and structured approach for continuous improvement across multiple pillars (operational excellence, security, cost optimization). The AWS Well-Architected Tool provides a framework for evaluating architectures against best practices, identifying high-risk issues, and creating actionable improvement plans. Integrating these reviews into the development lifecycle ensures that improvements are continuously identified and implemented as the architecture evolves. Option B (incorrect) focuses only on deployment automation, which is a part of operational excellence but does not cover the broader aspects of security, reliability, performance, or cost optimization. Option C (incorrect) describes a logging strategy, which is crucial for observability but is a component of a well-architected system, not the overarching framework for continuous improvement across all pillars. Option D (incorrect) focuses only on annual security audits, which is important but does not provide a continuous, holistic approach to improving the entire architecture across all Well-Architected pillars, and it represents the anti-pattern [ap-3.1-001] if not integrated into a continuous review process.', 44, 'm_44_4', 11, NULL, NULL),
  ('mock_42_all_1775004939674', 'A rapidly growing startup has built its core application on AWS using a microservices architecture. As the application scales, the leadership team wants to ensure that the architecture continuously adheres to AWS best practices for operational excellence, security, reliability, and cost optimization. They need a structured mechanism to regularly evaluate their architecture and drive ongoing improvements.', '["Implement a comprehensive suite of Amazon CloudWatch dashboards and alarms to monitor all key performance indicators and operational metrics.","Establish a process for regular reviews using the AWS Well-Architected Tool to identify and track architectural improvements across all pillars.","Automate all deployment processes using AWS CodePipeline and AWS CodeDeploy to ensure consistent and error-free releases.","Conduct annual penetration tests and vulnerability assessments to identify security weaknesses in the application and infrastructure."]'::jsonb, 'mcq', '{1}'::integer[], 'Option B (correct) is the most effective strategy for ensuring continuous adherence to AWS best practices across all pillars. The AWS Well-Architected Tool provides a structured framework for evaluating architectures against operational excellence, security, reliability, performance efficiency, cost optimization, and sustainability. Regular reviews help identify high-risk issues and create actionable improvement plans, fostering a culture of continuous architectural improvement. Option A (incorrect) focuses on observability, which is a critical component of operational excellence but doesn''t encompass the broader architectural review across all Well-Architected pillars. Option C (incorrect) focuses on deployment automation, which is also part of operational excellence but not a comprehensive architectural review mechanism. Option D (incorrect) focuses solely on security assessments, which are important but do not cover the other pillars of the Well-Architected Framework, and it represents the anti-pattern [ap-3.1-001] if not integrated into a continuous review process.', 44, 'm_44_4', 12, NULL, NULL);

-- ─────────────────────────────────────────
-- Module: m_44_2
-- ─────────────────────────────────────────

INSERT INTO public.mock_test_questions (mock_test_id, question_text, options, question_type, correct_answer, explanation, topic_id, module_id, question_order, pairs, matches)
VALUES
  ('mock_42_all_1775004939674', 'A software-as-a-service (SaaS) company needs to strengthen its security posture by centrally managing security findings and detecting potential threats across its AWS accounts. The security team is particularly concerned about identifying unusual or unauthorized activities and external access risks. They require a solution that aggregates findings and provides intelligent threat detection.', '["Deploy a third-party intrusion detection system (IDS) on Amazon EC2 instances within each VPC to monitor network traffic.","Configure AWS WAF on all Amazon CloudFront distributions and Application Load Balancers to block common web exploits.","Enable Amazon GuardDuty for intelligent threat detection and integrate its findings with AWS Security Hub for centralized security posture management.","Implement strict AWS IAM policies and regularly audit them using manual reviews to ensure the principle of least privilege."]'::jsonb, 'mcq', '{2}'::integer[], 'Option C (correct) provides a comprehensive and centralized solution for threat detection and security posture management. Amazon GuardDuty uses machine learning, anomaly detection, and threat intelligence to monitor for malicious activity and unauthorized behavior across AWS accounts and workloads. AWS Security Hub then aggregates findings from GuardDuty and other AWS security services (like IAM Access Analyzer, if enabled) into a single, normalized view, allowing the security team to prioritize and act on high-severity issues. Option A (incorrect) involves deploying a third-party IDS, which adds operational overhead and does not provide the integrated, intelligent threat detection across various AWS services that GuardDuty offers. Option B (incorrect) focuses on perimeter security (AWS WAF), which is important but does not provide comprehensive threat detection for internal activities or account-level threats, representing the anti-pattern [ap-3.2-001] of relying solely on perimeter security. Option D (incorrect) describes IAM policy management, which is fundamental for security but is a preventative control and does not actively detect threats or aggregate findings from various sources.', 44, 'm_44_2', 13, NULL, NULL),
  ('mock_42_all_1775004939674', 'A large enterprise needs to enhance its security posture by proactively identifying unintended external access to its Amazon S3 buckets and AWS IAM roles. The security team wants a service that can analyze resource policies and identify potential security risks, such as public access or cross-account access, without requiring manual policy review for every resource.', '["Use AWS IAM Access Analyzer to continuously monitor resource policies and identify findings for external access.","Configure Amazon GuardDuty to detect unusual API calls and potential threats to AWS resources.","Implement AWS Config rules to check for non-compliant S3 bucket policies and IAM role configurations.","Manually review the access control lists (ACLs) and bucket policies for all Amazon S3 buckets and IAM roles."]'::jsonb, 'mcq', '{0}'::integer[], 'Option A (correct) is specifically designed for this purpose. AWS IAM Access Analyzer helps identify resources in your organization and accounts, such as Amazon S3 buckets or IAM roles, that are shared with an external entity. It continuously monitors resource policies and generates findings for external access, allowing the security team to review and remediate potential risks proactively. Option B (incorrect) focuses on threat detection (GuardDuty), which identifies malicious activity but does not specifically analyze resource policies for unintended external access configurations. Option C (incorrect) uses AWS Config rules, which can check for compliance against predefined rules, but IAM Access Analyzer provides a more direct and comprehensive analysis for external access findings across supported resources. Option D (incorrect) involves manual review, which is highly inefficient, error-prone, and not scalable for a large enterprise with many resources.', 44, 'm_44_2', 14, NULL, NULL),
  ('mock_42_all_1775004939674', 'A global media company needs to enhance its threat detection capabilities across its multi-account AWS environment. They are particularly concerned about identifying potential malware, unauthorized access attempts, and unusual network activity that could indicate a compromise. The security team requires a solution that provides intelligent, continuous monitoring for these threats.', '["Implement strict network ACLs and security groups to restrict all inbound and outbound traffic to only necessary ports and protocols.","Enable Amazon GuardDuty across all accounts for continuous threat detection and integrate its findings with AWS Security Hub for centralized management.","Deploy host-based intrusion detection systems (HIDS) on all Amazon EC2 instances to monitor for suspicious activity.","Regularly review AWS CloudTrail logs for unusual API calls and Amazon VPC Flow Logs for suspicious network connections."]'::jsonb, 'mcq', '{1}'::integer[], 'Option B (correct) provides the most comprehensive and intelligent solution for continuous threat detection. Amazon GuardDuty uses machine learning, anomaly detection, and integrated threat intelligence to monitor for malicious activity and unauthorized behavior across AWS accounts and workloads, including potential malware and unusual network activity. Integrating its findings with AWS Security Hub provides a centralized view for managing and prioritizing security alerts. Option A (incorrect) focuses on perimeter security controls (NACLS, Security Groups), which are essential but do not detect threats that bypass these controls or originate from within the network, aligning with the anti-pattern [ap-3.2-001]. Option C (incorrect) involves deploying and managing HIDS on EC2 instances, which adds significant operational overhead and does not cover threats to other AWS services. Option D (incorrect) relies on manual review of CloudTrail and VPC Flow Logs, which is time-consuming, error-prone, and lacks the real-time, intelligent threat detection capabilities of GuardDuty.', 44, 'm_44_2', 15, NULL, NULL),
  ('mock_42_all_1775004939674', 'A large enterprise with multiple AWS accounts needs to gain a consolidated view of its security posture. The security team wants to aggregate security findings from various AWS services, such as Amazon GuardDuty and AWS IAM Access Analyzer, into a single dashboard and prioritize them based on severity to streamline incident response and compliance efforts.', '["Manually export findings from each security service and consolidate them into a custom dashboard using Amazon QuickSight.","Configure Amazon GuardDuty to send all findings directly to a central Amazon S3 bucket for archival and later analysis.","Utilize AWS Security Hub to aggregate and normalize security findings from integrated AWS services and third-party products, enabling centralized prioritization.","Implement AWS Config rules to continuously monitor resource compliance and generate alerts for any deviations from security baselines."]'::jsonb, 'mcq', '{2}'::integer[], 'Option C (correct) is precisely what AWS Security Hub is designed for. It provides a comprehensive view of your security posture across your AWS accounts, aggregating and normalizing security findings from various AWS services (like Amazon GuardDuty, AWS IAM Access Analyzer, AWS Config) and third-party security products. This allows the security team to prioritize and act on high-severity findings from a single dashboard. Option A (incorrect) involves manual export and custom dashboard creation, which is inefficient, prone to error, and lacks the real-time aggregation and normalization capabilities of Security Hub. Option B (incorrect) focuses on archival, which is important for compliance, but it does not provide a consolidated, actionable dashboard for real-time security posture management and prioritization. Option D (incorrect) uses AWS Config rules for compliance monitoring, which is a valuable security control but does not aggregate findings from other threat detection or access analysis services into a centralized security hub.', 44, 'm_44_2', 16, NULL, NULL);

-- ─────────────────────────────────────────
-- Module: m_44_5
-- ─────────────────────────────────────────

INSERT INTO public.mock_test_questions (mock_test_id, question_text, options, question_type, correct_answer, explanation, topic_id, module_id, question_order, pairs, matches)
VALUES
  ('mock_42_all_1775004939674', 'A digital marketing agency uses a large fleet of Amazon EC2 instances and Amazon RDS databases for its analytics platform. Over time, the resource utilization has become inconsistent, leading to significant over-provisioning and increased AWS costs. The operations team needs to identify the most cost-effective opportunities to right-size these resources without negatively impacting performance.', '["Utilize AWS Compute Optimizer to analyze historical utilization data and recommend optimal EC2 instance types and RDS database sizes.","Manually review Amazon CloudWatch metrics for each instance and database, then adjust their sizes based on average utilization over the last week.","Implement a schedule to stop all non-production EC2 instances during off-hours to reduce costs.","Migrate all EC2 instances to the latest generation instance types, assuming they offer better price-performance."]'::jsonb, 'mcq', '{0}'::integer[], 'Option A (correct) is the most efficient and recommended approach for right-sizing. AWS Compute Optimizer analyzes historical utilization data (CPU, memory, network, disk I/O) for EC2 instances, EBS volumes, Lambda functions, and RDS databases, providing specific recommendations for optimal instance types and sizes that balance performance and cost. Option B (incorrect) involves manual review of CloudWatch metrics, which is time-consuming, prone to human error, and may not account for burstable performance or specific workload patterns as effectively as Compute Optimizer. Option C (incorrect) is a valid cost-saving strategy for non-production environments but does not address the right-sizing of continuously running production resources. Option D (incorrect) assumes that newer generation instance types are always more cost-effective for all workloads without data-driven analysis, which can lead to suboptimal choices and potentially higher costs or performance issues.', 44, 'm_44_5', 17, NULL, NULL),
  ('mock_42_all_1775004939674', 'A technology company is looking to optimize the cost and performance of its existing Amazon EC2 instances. Many of these instances are running compute-intensive workloads that could benefit from Graviton processors. The operations team needs a data-driven approach to identify suitable candidates for migration to Graviton-based instances with the MOST efficiency.', '["Manually identify EC2 instances based on their current instance family and operating system, then perform a test migration.","Utilize AWS Compute Optimizer to analyze EC2 instance performance and utilization, providing recommendations for Graviton migration.","Implement Amazon CloudWatch custom metrics to track CPU utilization and memory usage for all EC2 instances and manually assess Graviton compatibility.","Migrate all existing EC2 instances to the latest generation x86-based instance types to ensure performance improvements."]'::jsonb, 'mcq', '{1}'::integer[], 'Option B (correct) is the most efficient and data-driven approach. AWS Compute Optimizer provides specific recommendations for migrating to Graviton-based instances by analyzing historical utilization and performance data. It helps identify which instances would benefit most from Graviton, estimates potential cost savings, and provides confidence scores, streamlining the migration process. Option A (incorrect) involves manual identification, which is time-consuming, prone to error, and lacks the data-driven insights provided by Compute Optimizer. Option C (incorrect) relies on manual assessment based on CloudWatch metrics, which is less efficient and comprehensive than Compute Optimizer''s automated analysis and recommendations. Option D (incorrect) suggests migrating to x86-based instances, which might offer some performance improvements but misses the opportunity for the significant cost and performance benefits of Graviton processors, especially for compatible workloads.', 44, 'm_44_5', 18, NULL, NULL),
  ('mock_42_all_1775004939674', 'A development team is managing several non-production Amazon EC2 instances that are frequently over-provisioned, leading to unnecessary cloud expenditure. The team needs a systematic way to identify and implement cost-saving opportunities by right-sizing these instances without compromising the performance required for development and testing activities.', '["Implement a schedule to stop all non-production EC2 instances during non-working hours and weekends.","Manually analyze Amazon CloudWatch CPU utilization metrics for each instance and reduce instance sizes if utilization is consistently low.","Utilize AWS Compute Optimizer to analyze historical utilization and recommend optimal EC2 instance types and sizes for cost savings.","Migrate all non-production instances to the smallest available instance types to minimize costs."]'::jsonb, 'mcq', '{2}'::integer[], 'Option C (correct) is the most effective and data-driven approach for right-sizing EC2 instances for cost optimization. AWS Compute Optimizer analyzes historical utilization data (CPU, memory, network, disk I/O) and provides specific recommendations for optimal EC2 instance types and sizes, balancing performance and cost. This ensures that development and testing activities have adequate resources while minimizing expenditure. Option A (incorrect) is a valid cost-saving strategy for non-production environments but does not address the right-sizing of instances that need to run during working hours. Option B (incorrect) involves manual analysis, which is time-consuming, prone to human error, and may not account for burstable performance or specific workload patterns as effectively as Compute Optimizer. Option D (incorrect) is an aggressive cost-cutting measure that is likely to negatively impact performance for development and testing, leading to developer frustration and reduced velocity.', 44, 'm_44_5', 19, NULL, NULL),
  ('mock_42_all_1775004939674', 'An existing application uses several Amazon EC2 instances that are consistently running at low CPU and memory utilization, leading to unnecessary costs. The operations team needs to identify the optimal EC2 instance types and sizes to reduce expenditure while ensuring adequate performance for the application''s workload.', '["Manually monitor Amazon CloudWatch metrics for each EC2 instance and reduce its size if utilization is below 20% for an extended period.","Implement a schedule to stop all EC2 instances during off-peak hours to minimize running costs.","Migrate all EC2 instances to the smallest available instance types to achieve maximum cost savings.","Utilize AWS Compute Optimizer to analyze historical utilization data and recommend right-sizing opportunities for EC2 instances."]'::jsonb, 'mcq', '{3}'::integer[], 'Option D (correct) is the most effective and data-driven approach for right-sizing EC2 instances. AWS Compute Optimizer analyzes historical utilization data (CPU, memory, network, disk I/O) and provides specific recommendations for optimal EC2 instance types and sizes that balance performance and cost. This ensures that the application has adequate resources while minimizing expenditure. Option A (incorrect) involves manual monitoring and decision-making, which is time-consuming, prone to human error, and may not account for burstable performance or specific workload patterns as effectively as Compute Optimizer. Option B (incorrect) is a valid cost-saving strategy for non-production environments or workloads that can tolerate downtime but does not address the right-sizing of continuously running instances. Option C (incorrect) is an aggressive cost-cutting measure that is likely to negatively impact application performance and reliability due to insufficient resources.', 44, 'm_44_5', 20, NULL, NULL);

