INSERT INTO public.mock_test_questions (mock_test_id, question_text, options, question_type, correct_answer, explanation, topic_id, module_id, question_order, pairs, matches)
VALUES
  ('mock_42_all_1775004939674', 'A company is migrating a monolithic Java application with a relational database from on-premises to AWS. The goal is to containerize the application for high availability and scalability while minimizing operational overhead for the compute layer. Which combination of AWS services should a Solutions Architect recommend?', '["Deploy the application on Amazon ECS using AWS Fargate and use Amazon RDS for the database.","Deploy the application on Amazon EC2 instances with Auto Scaling Groups and use Amazon RDS for the database.","Deploy the application on Amazon EKS and manage the underlying EC2 worker nodes, using Amazon RDS for the database.","Refactor the application into AWS Lambda functions and use Amazon DynamoDB for the database to maximize serverless benefits."]'::jsonb, 'mcq', '{0}'::integer[], 'Option A (correct) utilizes Amazon ECS with AWS Fargate, which provides a fully managed, serverless compute engine for containers, significantly minimizing operational overhead as there are no EC2 instances to manage. Amazon RDS offers a fully managed relational database service, aligning with the goal of high availability and scalability with reduced operational burden. Option B (incorrect) would require managing EC2 instances, including patching, security, and scaling of the underlying infrastructure, which increases operational overhead. Option C (incorrect) involves Amazon EKS, which, while powerful, introduces more complexity in managing the Kubernetes control plane and worker nodes (unless Fargate is used with EKS, but the option specifies managing EC2 worker nodes), thus increasing operational overhead compared to ECS on Fargate. Option D (incorrect) suggests refactoring the monolithic Java application into AWS Lambda functions and using Amazon DynamoDB. While this maximizes serverless benefits, it represents a significant refactoring effort, which is not the primary goal of minimizing operational overhead for the *current* containerized application.', 45, 'm_45_3', 1, NULL, NULL),
  ('mock_42_all_1775004939674', 'A media company needs to store petabytes of video assets for long-term archiving. These assets are rarely accessed, but when needed, retrieval times of several hours are acceptable. The primary requirement is to achieve the MOST cost-effective storage solution with high durability. Which Amazon S3 storage class should be recommended?', '["Amazon S3 Standard","Amazon S3 Glacier Deep Archive","Amazon S3 Intelligent-Tiering","Amazon S3 One Zone-Infrequent Access"]'::jsonb, 'mcq', '{1}'::integer[], 'Option B (correct) is Amazon S3 Glacier Deep Archive, which is designed for long-term archival of data that is accessed once or twice a year, with retrieval times in hours. It offers the lowest storage cost among all Amazon S3 storage classes, making it the most cost-effective solution for petabytes of rarely accessed archival data. Option A (incorrect) is Amazon S3 Standard, which is suitable for frequently accessed data and would be significantly more expensive for long-term archiving. Option C (incorrect) is Amazon S3 Intelligent-Tiering, which automatically moves data between access tiers based on access patterns. While it can optimize costs, it''s not the absolute lowest cost for data known to be rarely accessed for long-term archives. Option D (incorrect) is Amazon S3 One Zone-Infrequent Access, which stores data in a single Availability Zone, making it less durable than S3 Glacier Deep Archive and still more expensive for deep archiving.', 45, 'm_45_3', 2, NULL, NULL),
  ('mock_42_all_1775004939674', 'A financial application processes high-volume, low-latency transactions, requiring a fully managed NoSQL database. The database must provide consistent single-digit millisecond performance at any scale and automatically handle traffic spikes without manual intervention. Which AWS database service meets these requirements?', '["Amazon RDS for MySQL","Amazon Aurora","Amazon DynamoDB","Amazon OpenSearch Service"]'::jsonb, 'mcq', '{2}'::integer[], 'Option C (correct) is Amazon DynamoDB, a fully managed NoSQL key-value and document database that delivers consistent single-digit millisecond performance at any scale. It automatically scales throughput and storage to handle traffic spikes without manual intervention, perfectly aligning with the requirements for high-volume, low-latency transactions. Option A (incorrect) is Amazon RDS for MySQL, which is a relational database and does not inherently provide the consistent single-digit millisecond performance at arbitrary scale that DynamoDB offers for NoSQL workloads. Option B (incorrect) is Amazon Aurora, a relational database service compatible with MySQL and PostgreSQL. While highly scalable and performant, it is still a relational database and not purpose-built for the consistent low-latency NoSQL requirements described. Option D (incorrect) is Amazon OpenSearch Service, which is a managed service for search and analytics, not a transactional NoSQL database for high-volume, low-latency transactions.', 45, 'm_45_3', 3, NULL, NULL),
  ('mock_42_all_1775004939674', 'A company is rehosting a legacy application to Amazon EC2 instances. This application relies heavily on a shared file system (NFS) for configuration files and user-generated content, requiring high throughput and low latency access from multiple EC2 instances simultaneously. Which AWS storage service should be used to replace the on-premises NFS share?', '["Amazon S3","Amazon EBS volumes attached to each EC2 instance","Amazon FSx for Windows File Server","Amazon EFS"]'::jsonb, 'mcq', '{3}'::integer[], 'Option D (correct) is Amazon EFS (Elastic File System), which provides scalable, elastic, shared file storage that can be accessed concurrently by multiple Amazon EC2 instances. It supports the NFSv4 protocol, making it a direct and highly compatible replacement for on-premises NFS shares, while offering high throughput and low latency. Option A (incorrect) is Amazon S3, an object storage service, which is not suitable for applications requiring a traditional file system interface. Option B (incorrect) suggests using Amazon EBS volumes attached to each EC2 instance. EBS volumes are block storage and can only be attached to a single EC2 instance at a time (with some exceptions for multi-attach, but not for shared file system semantics across multiple instances for general purpose use cases). Option C (incorrect) is Amazon FSx for Windows File Server, which provides fully managed native Microsoft Windows file systems, but the legacy application uses NFS, implying a Linux/Unix environment.', 45, 'm_45_3', 4, NULL, NULL),
  ('mock_42_all_1775004939674', 'A company is modernizing an existing application that uses a PostgreSQL database. They need to migrate to a highly available, scalable, and fully managed relational database service on AWS that maintains full compatibility with PostgreSQL. Which AWS service is the most appropriate choice for this migration?', '["Amazon RDS for PostgreSQL","Amazon DynamoDB","Amazon OpenSearch Service","Amazon S3"]'::jsonb, 'mcq', '{0}'::integer[], 'Option A (correct) is Amazon RDS for PostgreSQL. This service provides a fully managed, highly available, and scalable PostgreSQL-compatible relational database. It allows for a straightforward migration of an existing PostgreSQL database while offloading operational tasks like patching, backups, and replication to AWS. Option B (incorrect) is Amazon DynamoDB, which is a NoSQL database and not compatible with PostgreSQL. Option C (incorrect) is Amazon OpenSearch Service, which is a search and analytics engine, not a relational database. Option D (incorrect) is Amazon S3, an object storage service, which is not a database.', 45, 'm_45_3', 5, NULL, NULL);

-- ─────────────────────────────────────────
-- Module: m_45_4
-- ─────────────────────────────────────────

INSERT INTO public.mock_test_questions (mock_test_id, question_text, options, question_type, correct_answer, explanation, topic_id, module_id, question_order, pairs, matches)
VALUES
  ('mock_42_all_1775004939674', 'A legacy batch processing system needs to be modernized to handle fluctuating workloads, process individual jobs asynchronously, and scale automatically without managing servers. The company aims to minimize operational costs and management overhead for this new architecture. Which combination of AWS services should a Solutions Architect recommend?', '["Amazon EC2 instances in an Auto Scaling Group processing messages from an Amazon SQS queue.","AWS Lambda functions triggered by messages in an Amazon SQS queue.","Amazon ECS tasks running on EC2 instances, processing jobs from an Amazon SQS queue.","Amazon EKS cluster with worker nodes processing jobs from an Amazon SQS queue."]'::jsonb, 'mcq', '{1}'::integer[], 'Option B (correct) uses AWS Lambda functions triggered by Amazon SQS messages. This combination provides a fully serverless architecture where Lambda functions execute only when messages are available, scaling automatically to meet demand without any server management. This significantly minimizes operational costs and management overhead. Option A (incorrect) involves managing Amazon EC2 instances, even with Auto Scaling Groups, which still incurs operational overhead for server maintenance and patching. Option C (incorrect) uses Amazon ECS tasks on EC2 instances, which also requires managing the underlying EC2 infrastructure, increasing operational overhead. Option D (incorrect) uses an Amazon EKS cluster, which is a complex container orchestration service that typically involves managing worker nodes (unless using Fargate with EKS, but the option implies worker nodes), leading to higher operational overhead.', 45, 'm_45_4', 6, NULL, NULL),
  ('mock_42_all_1775004939674', 'A company wants to modernize a monolithic application by extracting a new feature as a microservice. This new microservice needs to react to specific business events (e.g., ''Order Placed'') from the existing application and trigger a serverless workflow that involves multiple steps. The solution must be highly scalable and loosely coupled. Which AWS services should be combined?', '["Amazon SQS queue directly triggering an AWS Lambda function.","Amazon SNS topic publishing to multiple AWS Lambda functions.","Amazon EventBridge to capture events, triggering AWS Step Functions to orchestrate AWS Lambda functions.","Amazon ECS tasks running on AWS Fargate, polling for events from a custom API Gateway endpoint."]'::jsonb, 'mcq', '{2}'::integer[], 'Option C (correct) leverages Amazon EventBridge to capture and filter specific business events from the monolithic application. EventBridge can then trigger AWS Step Functions, which provides a serverless workflow orchestrator to manage multi-step processes, invoking AWS Lambda functions for individual tasks. This approach ensures high scalability, loose coupling, and a robust, serverless event-driven architecture. Option A (incorrect) uses Amazon SQS directly triggering Lambda. While serverless, SQS is primarily a message queue for point-to-point communication and lacks the advanced event routing and workflow orchestration capabilities needed for complex business events and multi-step processes. Option B (incorrect) uses Amazon SNS, which is a pub/sub messaging service. While it can fan out events, it doesn''t offer the rich event filtering and routing capabilities of EventBridge or the workflow orchestration of Step Functions. Option D (incorrect) uses Amazon ECS on AWS Fargate, which is a container service, not a serverless event-driven workflow. Polling an API Gateway endpoint for events is less efficient and not truly event-driven.', 45, 'm_45_4', 7, NULL, NULL),
  ('mock_42_all_1775004939674', 'A development team is refactoring a legacy application into microservices using containers. They require a fully managed container orchestration service that allows them to run containers without managing the underlying EC2 instances, focusing solely on application code and minimizing operational overhead. Which AWS service meets this requirement?', '["Amazon ECS on EC2 instances","Amazon EC2 instances with Docker installed","Amazon EKS with managed node groups","Amazon ECS on AWS Fargate"]'::jsonb, 'mcq', '{3}'::integer[], 'Option D (correct) is Amazon ECS on AWS Fargate. AWS Fargate is a serverless compute engine for Amazon ECS that allows you to run containers without having to provision, configure, or scale clusters of virtual machines. This significantly minimizes operational overhead as the team can focus entirely on their application code and container images. Option A (incorrect) uses Amazon ECS on EC2 instances, which requires managing the underlying EC2 instances, including patching, scaling, and maintenance. Option B (incorrect) involves directly managing Amazon EC2 instances with Docker, which offers no orchestration and high operational overhead. Option C (incorrect) uses Amazon EKS with managed node groups. While EKS is a powerful Kubernetes service, managing EKS clusters (even with managed node groups for worker nodes) still involves more operational complexity than ECS on Fargate, especially for teams prioritizing minimal infrastructure management.', 45, 'm_45_4', 8, NULL, NULL),
  ('mock_42_all_1775004939674', 'A company is modernizing its order processing system. New orders arrive as messages and need to be processed by several distinct microservices (e.g., inventory, payment, shipping). The system must ensure that each message is delivered reliably to all relevant services and processed asynchronously, with minimal message loss. Which AWS services should be combined?', '["Amazon SNS to fan out messages to multiple Amazon SQS queues, with each queue consumed by a dedicated microservice.","A single Amazon SQS queue consumed by all microservices.","AWS Lambda functions directly invoked by the order placement service.","Amazon EventBridge rules to filter and route messages to individual microservices via custom HTTP endpoints."]'::jsonb, 'mcq', '{0}'::integer[], 'Option A (correct) uses Amazon SNS to fan out messages to multiple Amazon SQS queues. SNS provides a publish/subscribe mechanism to deliver messages to multiple subscribers (in this case, SQS queues). Each SQS queue then acts as a reliable buffer for a dedicated microservice, ensuring asynchronous processing, reliable delivery, and minimal message loss, as SQS guarantees at-least-once delivery and messages persist until processed. Option B (incorrect) uses a single Amazon SQS queue for all microservices. This would make it difficult for multiple independent consumers to process the same message reliably without complex coordination, and it doesn''t inherently support fan-out. Option C (incorrect) involves direct invocation of AWS Lambda functions. While serverless, this approach lacks the message queuing for reliability and asynchronous buffering that SQS provides, potentially leading to message loss if Lambda invocations fail or throttle. Option D (incorrect) uses Amazon EventBridge to route messages to custom HTTP endpoints. While EventBridge is excellent for event routing, using custom HTTP endpoints for critical message delivery to microservices might introduce complexities around reliability, retries, and dead-letter queues that SQS inherently handles.', 45, 'm_45_4', 9, NULL, NULL),
  ('mock_42_all_1775004939674', 'A legacy application stores session state in local files on its servers, making it difficult to scale horizontally. To modernize, the session state needs to be moved to a highly available, serverless, and purpose-built database for key-value storage. Which AWS database service is the most suitable for this requirement?', '["Amazon Aurora Serverless","Amazon DynamoDB","Amazon RDS for MySQL","Amazon S3"]'::jsonb, 'mcq', '{1}'::integer[], 'Option B (correct) is Amazon DynamoDB, a fully managed, serverless NoSQL database service that provides fast and flexible key-value storage. It is highly available, scales automatically to handle any traffic volume, and is perfectly suited for storing session state due to its low-latency access and high throughput. Option A (incorrect) is Amazon Aurora Serverless, which is a relational database. While serverless, it is not purpose-built for key-value storage and might introduce unnecessary complexity for simple session state management. Option C (incorrect) is Amazon RDS for MySQL, a relational database service that is not serverless in the same way DynamoDB is and requires more management overhead for scaling and high availability. Option D (incorrect) is Amazon S3, an object storage service, which is not designed for low-latency, transactional database operations like session state management.', 45, 'm_45_4', 10, NULL, NULL);

-- ─────────────────────────────────────────
-- Module: m_45_2
-- ─────────────────────────────────────────

INSERT INTO public.mock_test_questions (mock_test_id, question_text, options, question_type, correct_answer, explanation, topic_id, module_id, question_order, pairs, matches)
VALUES
  ('mock_42_all_1775004939674', 'A company needs to migrate several hundred terabytes of on-premises file data (NFS shares) to Amazon S3 for long-term archival and occasional analytics. The migration must be performed securely and efficiently over the network, with minimal manual effort, without requiring physical appliance shipping. Which AWS service should be used?', '["AWS Snowball Edge","Manual SCP/rsync commands","AWS DataSync","AWS Database Migration Service (DMS)"]'::jsonb, 'mcq', '{2}'::integer[], 'Option C (correct) is AWS DataSync. DataSync is a data transfer service that makes it easier to automate moving data between on-premises storage and AWS storage services like Amazon S3. It is designed for secure, efficient, and high-performance online transfers of large datasets (hundreds of terabytes) with minimal manual effort. Option A (incorrect) is AWS Snowball Edge, which is part of the Snow Family and is primarily used for petabyte-scale data transfers or when network connectivity is limited or non-existent, involving physical appliance shipping. The scenario specifies ''over the network'' and ''minimal manual effort'' without physical shipping. Option B (incorrect) suggests manual SCP/rsync commands, which would involve significant manual effort, scripting, and management for hundreds of terabytes, making it inefficient and prone to errors. Option D (incorrect) is AWS Database Migration Service (DMS), which is specifically designed for migrating databases, not file data.', 45, 'm_45_2', 11, NULL, NULL),
  ('mock_42_all_1775004939674', 'An organization plans to migrate a large, complex Oracle database (10 TB) to Amazon Aurora PostgreSQL-Compatible Edition. They need to perform a heterogeneous database migration with minimal downtime, including both schema and data conversion. Which combination of AWS services should a Solutions Architect recommend?', '["AWS Application Migration Service (MGN) for server migration and manual data export/import.","AWS Snowball Edge for data transfer and AWS Schema Conversion Tool (SCT) for schema conversion.","AWS DataSync for data transfer and AWS Database Migration Service (DMS) for schema conversion.","AWS Database Migration Service (DMS) for data migration and AWS Schema Conversion Tool (SCT) for schema conversion."]'::jsonb, 'mcq', '{3}'::integer[], 'Option D (correct) is the combination of AWS Database Migration Service (DMS) and AWS Schema Conversion Tool (SCT). AWS DMS supports heterogeneous database migrations with minimal downtime by continuously replicating data from the source to the target database. AWS SCT assists in converting the database schema and code objects (like stored procedures, functions, and triggers) from Oracle to PostgreSQL-compatible format, making this the ideal solution for complex heterogeneous migrations. Option A (incorrect) uses AWS Application Migration Service (MGN), which is for server rehosting, not database migration, and manual data export/import would result in significant downtime. Option B (incorrect) uses AWS Snowball Edge for offline data transfer, which is not suitable for online database migration with minimal downtime. While SCT is correct for schema, Snowball Edge is not for this use case. Option C (incorrect) uses AWS DataSync, which is for file system transfers, not database migration. It also incorrectly assigns schema conversion to DMS, which primarily handles data migration.', 45, 'm_45_2', 12, NULL, NULL),
  ('mock_42_all_1775004939674', 'A company has an on-premises application server running on VMware that needs to be rehosted to Amazon EC2 with the LEAST amount of effort and downtime. The application is critical and cannot tolerate significant changes to its operating system or configuration. Which AWS service is best suited for this migration?', '["AWS Application Migration Service (MGN)","AWS DataSync","AWS Database Migration Service (DMS)","Manual creation of an Amazon Machine Image (AMI) from the on-premises server and import to AWS."]'::jsonb, 'mcq', '{0}'::integer[], 'Option A (correct) is AWS Application Migration Service (MGN). MGN is designed for rehosting (lift-and-shift) applications to AWS EC2 with minimal downtime and effort. It automates the migration of physical, virtual, and cloud servers into AWS, replicating the source server''s operating system, applications, and configuration to EC2 instances. Option B (incorrect) is AWS DataSync, which is a data transfer service for moving files, not entire servers. Option C (incorrect) is AWS Database Migration Service (DMS), which is specifically for migrating databases, not application servers. Option D (incorrect) suggests manual AMI creation and import. While possible, this approach is significantly more labor-intensive, error-prone, and typically results in higher downtime compared to using a specialized service like MGN.', 45, 'm_45_2', 13, NULL, NULL),
  ('mock_42_all_1775004939674', 'A research institution needs to migrate 500 TB of scientific data from an isolated on-premises data center with limited internet connectivity to Amazon S3. The migration must be completed within a few weeks, and network bandwidth is a major bottleneck. Which AWS service offers the most efficient solution for this data transfer?', '["AWS DataSync over the existing internet connection.","AWS Snowball Edge","Establishing an AWS Direct Connect connection.","Uploading data manually via a VPN connection."]'::jsonb, 'mcq', '{1}'::integer[], 'Option B (correct) is AWS Snowball Edge. For large datasets (hundreds of terabytes to petabytes) from locations with limited or no internet connectivity, the AWS Snowball Edge device provides a secure and efficient offline data transfer method. It physically ships the data to AWS, bypassing network bottlenecks and allowing the migration to be completed within the desired timeframe. Option A (incorrect) suggests AWS DataSync over the existing internet connection. While DataSync is efficient for online transfers, it would be severely hampered by the limited internet connectivity and would likely fail to meet the ''few weeks'' deadline for 500 TB. Option C (incorrect) is establishing an AWS Direct Connect connection. While Direct Connect provides dedicated network bandwidth, it has a lead time for provisioning and installation, which might not fit the ''few weeks'' deadline, and it still requires sufficient bandwidth capacity to transfer 500 TB over the network. Option D (incorrect) suggests uploading data manually via a VPN connection. This would be extremely slow and impractical for 500 TB over limited internet, making it the least efficient option.', 45, 'm_45_2', 14, NULL, NULL),
  ('mock_42_all_1775004939674', 'A company is migrating an entire data center to AWS, involving hundreds of server and database migrations across different teams and using various migration tools. The leadership team requires a centralized dashboard to track the overall progress, status, and health of all ongoing migrations. Which AWS service provides this capability?', '["AWS Application Discovery Service","AWS Control Tower","AWS Migration Hub","AWS Systems Manager"]'::jsonb, 'mcq', '{2}'::integer[], 'Option C (correct) is AWS Migration Hub. AWS Migration Hub provides a single location to track the progress of application migrations across multiple AWS and partner solutions. It offers a centralized dashboard that shows the status of migrations from various tools, providing visibility into the overall migration portfolio. Option A (incorrect) is AWS Application Discovery Service, which is used to gather information about on-premises servers and applications to aid in migration planning, not to track ongoing migration progress. Option B (incorrect) is AWS Control Tower, which helps set up and govern a secure, multi-account AWS environment, but it does not track individual migration progress. Option D (incorrect) is AWS Systems Manager, which provides operational insights and automation for AWS resources, but it''s not specifically designed as a centralized migration tracking dashboard.', 45, 'm_45_2', 15, NULL, NULL);

-- ─────────────────────────────────────────
-- Module: m_45_1
-- ─────────────────────────────────────────

INSERT INTO public.mock_test_questions (mock_test_id, question_text, options, question_type, correct_answer, explanation, topic_id, module_id, question_order, pairs, matches)
VALUES
  ('mock_42_all_1775004939674', 'A Solutions Architect is advising a company on migrating its applications to AWS. The company has a mix of legacy applications, some with high technical debt but business-critical, and others modern and well-architected. The architect must recommend a strategy that maximizes cloud-native benefits for suitable applications while minimizing initial migration effort for others. Which approach aligns with AWS best practices?', '["Apply the 7 Rs of migration, evaluating each workload to determine if rehost, replatform, or refactor is most appropriate based on business value and technical complexity.","Rehost all applications to Amazon EC2 instances to minimize initial migration effort, then modernize them later.","Refactor all applications into serverless microservices to maximize cloud-native benefits from day one.","Retire all legacy applications immediately to eliminate technical debt and focus only on modern applications."]'::jsonb, 'mcq', '{0}'::integer[], 'Option A (correct) aligns with AWS best practices by advocating for the 7 Rs of migration (Retain, Retire, Rehost, Replatform, Repurchase, Refactor, Relocate). This approach involves evaluating each workload individually to determine the optimal migration strategy based on its business value, technical complexity, and desired cloud benefits. This allows for a balanced approach, minimizing effort where appropriate (e.g., rehost for legacy apps) and maximizing cloud-native benefits for suitable applications (e.g., refactor for modern apps). Option B (incorrect) represents the anti-pattern of defaulting to rehost for all workloads (ap-4.1-001). While it minimizes initial effort, it moves technical debt to the cloud without realizing cloud-native benefits for applications that could be modernized. Option C (incorrect) suggests refactoring all applications immediately. This would incur significant upfront cost, effort, and risk, which might not be feasible or necessary for all applications. Option D (incorrect) recommends retiring all legacy applications. This is an extreme measure that could lead to loss of critical business functionality if not carefully evaluated.', 45, 'm_45_1', 16, NULL, NULL),
  ('mock_42_all_1775004939674', 'A company has identified an old, rarely used application that incurs significant maintenance costs on-premises. This application provides minimal business value and its functionality is largely duplicated by a newer system. The Solutions Architect needs to recommend the MOST cost-effective approach for this application during cloud migration planning. Which of the 7 Rs of migration should be applied?', '["Rehost the application to Amazon EC2.","Retire the application.","Replatform the application to Amazon ECS.","Refactor the application into AWS Lambda functions."]'::jsonb, 'mcq', '{1}'::integer[], 'Option B (correct) is to Retire the application. For applications that provide minimal business value, incur significant maintenance costs, and have duplicated functionality, decommissioning them is the most cost-effective approach. This eliminates ongoing operational expenses and avoids unnecessary migration costs. Option A (incorrect) suggests rehosting the application. This would incur new cloud costs for an application that provides little value, making it inefficient. Option C (incorrect) suggests replatforming the application. This would require effort and cost to move it to a container platform, which is not justified for an application with minimal business value. Option D (incorrect) suggests refactoring the application. This is the most intensive and costly migration strategy and would be entirely inappropriate for an application that should be decommissioned.', 45, 'm_45_1', 17, NULL, NULL),
  ('mock_42_all_1775004939674', 'A company is preparing a business case for cloud migration. They need to compare the current total cost of ownership (TCO) of their on-premises infrastructure with the estimated costs of running their workloads on AWS, including compute, storage, networking, and operational expenses. Which activity is crucial for this comparison?', '["Focus solely on the compute costs of running virtual machines on AWS versus on-premises servers.","Utilize AWS Migration Hub to track the progress of migration waves and associated costs.","Conduct a detailed Total Cost of Ownership (TCO) analysis, factoring in server, storage, network, power, cooling, and labor costs for on-premises versus AWS.","Migrate a small subset of applications to AWS and then extrapolate the costs for the entire portfolio."]'::jsonb, 'mcq', '{2}'::integer[], 'Option C (correct) is to conduct a detailed Total Cost of Ownership (TCO) analysis. A comprehensive TCO analysis involves comparing all relevant costs, including direct costs (hardware, software licenses, data center space, power, cooling, networking) and indirect costs (IT labor, maintenance, operational overhead) for both on-premises and AWS environments. This provides a holistic view necessary for a robust business case. Option A (incorrect) suggests focusing solely on compute costs, which would provide an incomplete and inaccurate TCO comparison, neglecting significant expenses like storage, networking, and labor. Option B (incorrect) suggests utilizing AWS Migration Hub. While Migration Hub is excellent for tracking migration progress, it is not designed for upfront TCO analysis and cost comparison. Option D (incorrect) suggests migrating a small subset and extrapolating. While a pilot migration can provide valuable insights, it should ideally follow a TCO analysis, and extrapolation alone might not accurately reflect the costs for the entire, diverse portfolio.', 45, 'm_45_1', 18, NULL, NULL),
  ('mock_42_all_1775004939674', 'A Solutions Architect is evaluating a critical, tightly coupled monolithic application for migration. The application has a complex architecture with many interdependencies and a high cost of change. The business prioritizes minimal disruption and speed of migration over immediate cloud-native optimization. Which migration strategy is most appropriate for this workload?', '["Refactor the application into microservices immediately to achieve cloud-native benefits.","Replatform the application to containers on Amazon ECS or Amazon EKS.","Retire the application due to its high complexity and technical debt.","Rehost (lift and shift) the application to Amazon EC2 instances, then consider modernization in a later phase."]'::jsonb, 'mcq', '{3}'::integer[], 'Option D (correct) is to Rehost (lift and shift) the application to Amazon EC2 instances. For critical, tightly coupled monolithic applications with high cost of change, where the business prioritizes minimal disruption and speed, rehosting is often the most appropriate initial strategy. It allows the application to run on AWS with minimal changes, reducing immediate risk and accelerating the migration timeline. Modernization can then be considered in a subsequent phase. Option A (incorrect) suggests refactoring immediately. This is a high-effort, high-risk strategy that would cause significant disruption and delay, directly conflicting with the business''s priorities. Option B (incorrect) suggests replatforming to containers. While a step towards modernization, it still involves significant changes and effort compared to a pure rehost, potentially increasing disruption. Option C (incorrect) suggests retiring the application. This is not an option for a critical application.', 45, 'm_45_1', 19, NULL, NULL),
  ('mock_42_all_1775004939674', 'A company needs to gather detailed information about its on-premises server specifications, running processes, and network dependencies across hundreds of servers to inform migration planning and TCO analysis. This discovery process must be automated and comprehensive. Which AWS service is designed for this purpose?', '["AWS Migration Hub","AWS Systems Manager","AWS Application Discovery Service","Manual inventory collection using spreadsheets and interviews."]'::jsonb, 'mcq', '{2}'::integer[], 'Option C (correct) is AWS Application Discovery Service. This service helps enterprises plan migration projects by gathering information about on-premises data centers. It automatically collects server specifications, running processes, performance data, and network dependencies, providing a comprehensive inventory that is crucial for migration planning and TCO analysis. Option A (incorrect) is AWS Migration Hub, which is used to track the progress of migrations, not to discover on-premises assets. Option B (incorrect) is AWS Systems Manager, which provides operational insights and automation for AWS resources and hybrid environments, but its primary purpose is not the initial discovery of a comprehensive on-premises application portfolio. Option D (incorrect) suggests manual inventory collection. This is inefficient, prone to errors, and not scalable for hundreds of servers, failing the requirement for an automated and comprehensive process.', 45, 'm_45_1', 20, NULL, NULL),
  ('mock_42_all_1775004939674', 'A company is migrating an on-premises application that processes sensitive customer data and stores it in a Microsoft SQL Server database. The migration strategy is to rehost the application to Amazon EC2 and the database to Amazon RDS for SQL Server. During the migration, the company must ensure that all data in transit and at rest is encrypted, and that the database migration has a robust fallback plan. Which anti-pattern should the Solutions Architect specifically avoid during the database migration?', '["Defaulting to rehost for all workloads to minimize migration effort.","Attempting online database migration without a fallback plan or cutover window.","Migrating the application and database without prior performance testing.","Using manual data transfer methods instead of automated services like AWS DMS."]'::jsonb, 'mcq', '{1}'::integer[], 'Option B (correct) directly addresses the anti-pattern [ap-4.2-001]: Attempting online database migration without a fallback plan or cutover window. Database migrations carry data integrity risks, and it is critical to always run AWS DMS in parallel with validation, maintain the ability to roll back to the source database, and plan a maintenance window cutover with a tested validation checklist. Option A (incorrect) refers to anti-pattern [ap-4.1-001] (Defaulting to rehost for all workloads), which is about overall migration strategy, not specific to database migration risks. Option C (incorrect) is a general best practice for any migration but not a specific anti-pattern related to the integrity and fallback of an online database migration. Option D (incorrect) is about efficiency and automation, not the critical risk of data integrity and rollback during an online database migration.', 45, 'm_45_1', 21, NULL, NULL);

